make("ModuleScript", "AbyssalAura", i3, [=[
--!strict
--[[
	AbyssalAura (key 3, toggle loop)
	================================
	Charge-up aura that follows the caster until stopped:
	  * black spiky flames rising from the feet (looping emitter)
	  * a pulsing white glow + PointLight at the base
	  * two white ring trails orbiting at different tilts
	  * small black shards drifting upward in helical loops
	  * a cracked dark decal spreading under the player (re-spawned when
	    they move away from it)

	Boss-tier layers: a charge-up burst (rocks erupting in a ring + a black
	ForceField shell), a looping column of ink wisps and rising sparks,
	electricity crackling over the body, and a white ground pulse every
	GroundPulse.Interval. Stopping adds impact frames, focus lines, an FOV
	punch, layered spheres and a second rock ring. Body-attached sizes
	scale with the caster (a world boss scaled to 3x gets a 3x aura).

	Play(character) starts it (ignored if already active).
	Stop(character) ends it with a heavy white flash burst. The aura also
	stops itself when the character dies / is removed, or after
	Config.Spells.AbyssalAura.MaxDuration seconds, so it can never leak.
]]

local Config = require(script.Parent.Parent.Config)
local Util = script.Parent.Parent.Util
local CameraShake = require(Util.CameraShake)
local Emit = require(Util.Emit)
local Flash = require(Util.Flash)
local FocusLines = require(Util.FocusLines)
local GroundDecal = require(Util.GroundDecal)
local ImpactFrame = require(Util.ImpactFrame)
local Lightning = require(Util.Lightning)
local OrbitTrail = require(Util.OrbitTrail)
local RockRing = require(Util.RockRing)
local Shockwave = require(Util.Shockwave)
local Sphere = require(Util.Sphere)
local Types = require(Util.Types)

local Spell = Config.Spells.AbyssalAura
local C = Spell.VFX

type Shard = { Part: Part, Angle: number, Radius: number, Phase: number }

local AbyssalAura = {}

-- character -> function that ends that character's aura
local active: { [Model]: () -> () } = {}

local function stopBurst(position: Vector3)
	local cframe = CFrame.new(position)
	Flash.Impact(position, C.StopFlash)
	Emit.burstAt(cframe, C.StopSparks)
	Emit.burstAt(cframe, { Spec = Config.Emitters.CoreFlare, Count = C.StopCoreCount })
	Shockwave.Ground(position, C.StopRing)
	CameraShake.Preset(C.StopShake, position)
	-- Boss-tier layers.
	ImpactFrame.Preset(C.StopImpact, position)
	FocusLines.Play(position, C.StopFocus)
	CameraShake.PunchPreset(C.StopPunch, position)
	Sphere.Layers(position, C.StopSpheres)
	RockRing.Ring(position, C.StopRocks)
end

local function isAlive(character: Model): boolean
	if not character.Parent then
		return false
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	return humanoid == nil or humanoid.Health > 0
end

function AbyssalAura.Play(character: Model, _targetPosition: Vector3)
	if active[character] then
		return
	end
	local root = Emit.root(character)
	if root == nil then
		return
	end

	local group = Instance.new("Folder")
	group.Name = "AbyssalAura"
	group.Parent = Emit.folder()

	-- Feet from HipHeight when available (correct for scaled boss rigs).
	local function feetPosition(part: BasePart): Vector3
		return Emit.feet(character) or (part.CFrame * CFrame.new(C.FootOffset)).Position
	end
	local scale = Emit.characterScale(character)

	-- Base: flames + glow + light, all following the feet.
	local base = Emit.anchor(CFrame.new(feetPosition(root)), nil, C.BaseSize * scale)
	base.Parent = group
	local flames = Emit.emitter(base, C.Flames.Spec)
	local glow = Emit.emitter(base, C.BaseGlow.Spec)
	local inkPillar = Emit.emitter(base, C.InkPillar.Spec)
	local risingSparks = Emit.emitter(base, C.RisingSparks.Spec)

	-- Charge-up burst.
	local startFeet = feetPosition(root)
	RockRing.Ring(startFeet, C.ChargeRocks)
	Sphere.Burst(root.Position, C.ChargeSphere)
	CameraShake.Preset(C.ChargeShake, startFeet)
	local light = Instance.new("PointLight")
	light.Color = C.Light.Color
	light.Brightness = C.Light.Brightness
	light.Range = C.Light.Range
	light.Shadows = false
	light.Parent = base

	-- Orbiting rings.
	local style: Types.TrailStyle = {
		Width = C.Orbit.Width,
		Lifetime = C.Orbit.Lifetime,
		Color = C.Orbit.Color,
		Transparency = C.Orbit.Transparency,
		LightEmission = C.Orbit.LightEmission,
		Brightness = C.Orbit.Brightness,
	}
	local orbits: { Types.Handle } = {}
	for _, orbit in C.Orbit.Trails do
		table.insert(orbits, OrbitTrail.OnCharacter(character, orbit, style, nil))
	end

	-- Drifting shards.
	local shards: { Shard } = {}
	for i = 1, C.Shards.Count do
		local part = Emit.part(C.Shards.Size, C.Shards.Color, C.Shards.Material)
		part.Name = "AuraShard"
		part.Transparency = 1
		part.Parent = group
		table.insert(shards, {
			Part = part,
			Angle = (i / C.Shards.Count) * math.pi * 2,
			Radius = Emit.random(C.Shards.MinRadius, C.Shards.MaxRadius),
			Phase = Emit.random(0, C.Shards.LoopHeight),
		})
	end

	-- Ground decal, re-spawned under the player when they wander off.
	local decalCenter = feetPosition(root)
	local decal = GroundDecal.Spawn(decalCenter, C.Decal)

	local finished = false
	local function finish()
		if finished then
			return
		end
		finished = true
		active[character] = nil
		flames.Enabled = false
		glow.Enabled = false
		inkPillar.Enabled = false
		risingSparks.Enabled = false
		for _, orbit in orbits do
			orbit.Stop()
		end
		decal.Stop()
		for _, shard in shards do
			Emit.tween(shard.Part, C.Orbit.Lifetime, { Transparency = 1 })
		end
		Emit.tween(light, C.Orbit.Lifetime, { Brightness = 0 })
		-- Let the last flame particles finish before destroying the group.
		local linger = math.max(
			C.Flames.Spec.Lifetime.Max,
			C.BaseGlow.Spec.Lifetime.Max,
			C.InkPillar.Spec.Lifetime.Max,
			C.RisingSparks.Spec.Lifetime.Max
		)
		Emit.cleanup(group, linger)
		stopBurst(base.Position)
	end

	local arcTimer = 0
	local pulseTimer = 0
	local stopStep = Emit.step(Spell.MaxDuration, function(_alpha, dt, elapsed)
		local currentRoot = Emit.root(character)
		if currentRoot == nil or not group.Parent or not isAlive(character) then
			return true
		end
		local feet = feetPosition(currentRoot)
		base.CFrame = CFrame.new(feet)
		light.Brightness = C.Light.Brightness + math.sin(elapsed * C.PulseSpeed) * C.PulseAmplitude

		for _, shard in shards do
			local height = (shard.Phase + elapsed * C.Shards.RiseSpeed) % C.Shards.LoopHeight
			local loopAlpha = height / C.Shards.LoopHeight
			local angle = shard.Angle + elapsed * C.Shards.SpinSpeed
			local tumble = elapsed * C.Shards.TumbleSpeed
			shard.Part.CFrame = CFrame.new(
				feet + Vector3.new(math.cos(angle) * shard.Radius, height, math.sin(angle) * shard.Radius)
			) * CFrame.Angles(tumble, tumble, 0)
			-- Fade in at the bottom of the loop and out at the top so the
			-- wrap-around is invisible.
			shard.Part.Transparency = 1 - math.sin(math.pi * loopAlpha)
		end

		-- Electricity crackling over the body.
		arcTimer += dt
		if arcTimer >= C.ArcPulse.Interval then
			arcTimer = 0
			Lightning.Crackle(currentRoot.Position, C.ArcPulse.Radius * scale, C.ArcPulse.Count, C.ArcPulse.Bolt)
		end
		-- Periodic white ground pulse.
		pulseTimer += dt
		if pulseTimer >= C.GroundPulse.Interval then
			pulseTimer = 0
			Shockwave.Ground(feet, C.GroundPulse.Ring)
		end

		if (feet - decalCenter).Magnitude > C.DecalRespawnDistance then
			decal.Stop()
			decalCenter = feet
			decal = GroundDecal.Spawn(decalCenter, C.Decal)
		end
		return false
	end, finish)

	active[character] = stopStep
end

function AbyssalAura.Stop(character: Model)
	local stop = active[character]
	if stop then
		stop()
	end
end

-- Typed export: the checker verifies this module matches Types.SpellModule.
local module: Types.SpellModule = { Play = AbyssalAura.Play, Stop = AbyssalAura.Stop }
return module
]=])
make("ModuleScript", "CelestialVerdict", i3, [=[
--!strict
--[[
	CelestialVerdict (key 8, ultimate)
	==================================
	1. The sky dims: Lighting.ExposureCompensation is tweened down and a
	   temporary ColorCorrectionEffect desaturates the world.
	2. A giant white rune circle draws itself high above the target and
	   rotates.
	3. A massive pillar of white light crashes down (beams whose lower end
	   races from the circle to the ground), outlined by crackling bolts
	   and wrapped in black ink smoke and ink trails spiralling upward.
	4. Impact: ultimate flare streak + screen flash, double shockwave ring,
	   heavy camera shake, crater-sized crack decal, and dozens of shards
	   hanging mid-air before falling.
	5. The pillar fades and Lighting is restored to its original values.

	Boss-tier layers: lightning crawls over the rune circle while it charges
	and focus lines snap toward it; the impact adds a 5-step impact-frame
	sequence, a huge FOV punch, three nested spheres (white core, black and
	white ForceField shells), two rings of erupting rocks, and eight smaller
	light spears slamming down around the main pillar.

	Overlapping casts share one dim: a reference count makes sure Lighting
	is only restored after the last cast finishes.
]]

local Lighting = game:GetService("Lighting")

local Config = require(script.Parent.Parent.Config)
local Util = script.Parent.Parent.Util
local CameraShake = require(Util.CameraShake)
local Debris = require(Util.Debris)
local Emit = require(Util.Emit)
local Flash = require(Util.Flash)
local FocusLines = require(Util.FocusLines)
local GroundDecal = require(Util.GroundDecal)
local ImpactFrame = require(Util.ImpactFrame)
local Lightning = require(Util.Lightning)
local OrbitTrail = require(Util.OrbitTrail)
local RockRing = require(Util.RockRing)
local RuneCircle = require(Util.RuneCircle)
local Shockwave = require(Util.Shockwave)
local Sphere = require(Util.Sphere)
local Types = require(Util.Types)

local C = Config.Spells.CelestialVerdict.VFX
local Dim = C.SkyDim

local CelestialVerdict = {}

---------------------------------------------------------------------------
-- Sky dimming (reference counted).
---------------------------------------------------------------------------
local dimCount = 0
local savedExposure = 0
local correction: ColorCorrectionEffect? = nil
local restoreToken = 0

local function dimSky()
	dimCount += 1
	restoreToken += 1
	if dimCount == 1 and correction == nil then
		savedExposure = Lighting.ExposureCompensation
	end
	local effect: ColorCorrectionEffect
	local existing = correction
	if existing then
		effect = existing
	else
		effect = Instance.new("ColorCorrectionEffect")
		effect.Name = "CelestialVerdictDim"
		effect.Parent = Lighting
		correction = effect
	end
	Emit.tween(Lighting, Dim.FadeIn, { ExposureCompensation = savedExposure + Dim.ExposureCompensation })
	Emit.tween(effect, Dim.FadeIn, {
		Saturation = Dim.Saturation,
		Contrast = Dim.Contrast,
		Brightness = Dim.Brightness,
	})
end

local function restoreSky()
	dimCount = math.max(dimCount - 1, 0)
	if dimCount > 0 then
		return
	end
	restoreToken += 1
	local token = restoreToken
	Emit.tween(Lighting, Dim.FadeOut, { ExposureCompensation = savedExposure })
	local effect = correction
	if effect then
		local tween = Emit.tween(effect, Dim.FadeOut, { Saturation = 0, Contrast = 0, Brightness = 0 })
		tween.Completed:Once(function()
			-- A new cast may have started while we were restoring.
			if token == restoreToken and dimCount == 0 then
				effect:Destroy()
				if correction == effect then
					correction = nil
				end
			end
		end)
	end
end

---------------------------------------------------------------------------
-- The light pillar.
---------------------------------------------------------------------------
type PillarParams = {
	CrashTime: number,
	Duration: number,
	FadeTime: number,
	CoreWidth: number,
	GlowWidth: number,
	GlowTransparency: number,
}

local function pillar(sky: Vector3, ground: Vector3, P: PillarParams)
	local total = P.CrashTime + P.Duration + P.FadeTime
	local host = Emit.anchor(CFrame.new(ground), total)
	local top = Emit.attachment(host, CFrame.new(sky - ground))
	local bottom = Emit.attachment(host, CFrame.new(sky - ground))

	local function beam(width: number, transparency: number): Beam
		local b = Instance.new("Beam")
		b.Attachment0 = top
		b.Attachment1 = bottom
		b.Color = ColorSequence.new(C.Pillar.Color)
		b.LightEmission = 1
		b.LightInfluence = 0
		b.Brightness = C.Pillar.Brightness
		b.FaceCamera = true
		b.Segments = 1
		b.Width0 = width
		b.Width1 = width
		b.Transparency = NumberSequence.new(transparency)
		b.Parent = host
		return b
	end
	local glow = beam(P.GlowWidth, P.GlowTransparency)
	local core = beam(P.CoreWidth, 0)

	Emit.step(total, function(_alpha, _dt, elapsed)
		if not host.Parent then
			return true
		end
		-- Crash: the lower end races down to the ground.
		local crash = math.clamp(elapsed / P.CrashTime, 0, 1)
		bottom.Position = (sky - ground) * (1 - crash * crash)
		-- Fade: shrink + turn transparent.
		local fadeStart = P.CrashTime + P.Duration
		if elapsed > fadeStart then
			local fade = math.clamp((elapsed - fadeStart) / P.FadeTime, 0, 1)
			core.Width0 = P.CoreWidth * (1 - fade)
			core.Width1 = core.Width0
			glow.Width0 = P.GlowWidth * (1 - fade)
			glow.Width1 = glow.Width0
			core.Transparency = NumberSequence.new(fade)
			glow.Transparency = NumberSequence.new(P.GlowTransparency + (1 - P.GlowTransparency) * fade)
		end
		return false
	end)
end

function CelestialVerdict.Play(_character: Model, targetPosition: Vector3)
	local groundCFrame = Emit.groundCFrame(targetPosition)
	local ground = groundCFrame.Position
	local sky = ground + Vector3.yAxis * C.CircleHeight

	-------------------------------------------------------------------
	-- 1-2. Sky dims, rune circle appears high above.
	-------------------------------------------------------------------
	dimSky()
	-- Restore is scheduled up front so Lighting always comes back, even if
	-- something later in this function errors.
	task.delay(C.CircleTime + C.Pillar.CrashTime + C.Pillar.Duration + C.Pillar.FadeTime, restoreSky)
	RuneCircle.Spawn(CFrame.new(sky), C.Circle)
	-- Lightning crawling over the circle while it charges.
	local arcs = C.ChargeArcs
	for _ = 1, arcs.Count do
		Lightning.Bolt(function()
			local a = Emit.random(0, math.pi * 2)
			local b = a + Emit.random(-arcs.Span, arcs.Span)
			local r = arcs.Radius
			return sky + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r),
				sky + Vector3.new(math.cos(b) * r, 0, math.sin(b) * r)
		end, arcs.Bolt)
	end
	task.wait(C.CircleTime - C.ChargeFocus.Duration)
	FocusLines.Play(sky, C.ChargeFocus)
	task.wait(C.ChargeFocus.Duration)

	-------------------------------------------------------------------
	-- 3. Pillar crashes down.
	-------------------------------------------------------------------
	pillar(sky, ground, C.Pillar)

	local boltParams = C.PillarBolts.Bolt
	for i = 1, C.PillarBolts.Count do
		local angle = (i / C.PillarBolts.Count) * math.pi * 2
		local offset = Vector3.new(math.cos(angle), 0, math.sin(angle)) * C.PillarBolts.Radius
		Lightning.Strike(sky + offset, ground + offset, boltParams)
	end

	local spiral = C.InkSpiral
	local spiralSize = Vector3.new(spiral.Radius * 2, Config.General.AnchorSize.Y, spiral.Radius * 2)
	local spiralHost = Emit.anchor(CFrame.new(ground), C.Pillar.Duration + spiral.Spec.Lifetime.Max, spiralSize)
	Emit.pulse(Emit.emitter(spiralHost, spiral.Spec), spiral.Count, spiral.Interval, C.Pillar.Duration)

	local inkStyle: Types.TrailStyle = {
		Width = C.InkTrails.Width,
		Lifetime = C.InkTrails.Lifetime,
		Color = C.InkTrails.Color,
		Transparency = C.InkTrails.Transparency,
		LightEmission = C.InkTrails.LightEmission,
		Brightness = C.InkTrails.Brightness,
	}
	local center = CFrame.new(ground)
	for i = 1, C.InkTrails.Count do
		OrbitTrail.Start(function(): CFrame?
			return center
		end, {
			Radius = C.InkTrails.Radius,
			Height = 0,
			Speed = C.InkTrails.Speed,
			Tilt = Vector3.zero,
			Phase = (i / C.InkTrails.Count) * math.pi * 2,
			RiseSpeed = C.InkTrails.RiseSpeed,
		}, inkStyle, C.Pillar.Duration)
	end

	task.wait(C.Pillar.CrashTime)

	-------------------------------------------------------------------
	-- 4. Impact.
	-------------------------------------------------------------------
	Flash.Impact(ground, C.Flash)
	Emit.burstAt(CFrame.new(ground), { Spec = Config.Emitters.CoreFlare, Count = C.CoreCount })
	Emit.burstAt(CFrame.new(ground), C.Sparks)
	Emit.burstAt(CFrame.new(ground), C.Smoke)
	for _, ring in C.Rings do
		Shockwave.Ground(ground, ring)
	end
	GroundDecal.Spawn(ground, C.Decal)
	Debris.Shards(ground, C.Shards)
	CameraShake.Preset(C.Shake, ground)

	-- Boss-tier layers.
	ImpactFrame.Preset(C.Impact, ground)
	FocusLines.Play(ground, C.Focus)
	CameraShake.PunchPreset(C.Punch, ground)
	Sphere.Layers(ground, C.Spheres)
	RockRing.Ring(ground, C.Rocks)
	task.delay(C.OuterRocksDelay, RockRing.Ring, ground, C.OuterRocks)

	-- Light spears slamming down around the main pillar.
	local spears = C.Spears
	task.wait(spears.Delay)
	for i = 1, spears.Count do
		local angle = (i / spears.Count) * math.pi * 2 + Emit.random(-spears.AngleJitter, spears.AngleJitter)
		local spot = Emit.groundAt(ground + Vector3.new(math.cos(angle), 0, math.sin(angle)) * spears.Radius)
		pillar(spot + Vector3.yAxis * spears.Height, spot, spears)
		task.delay(spears.CrashTime, function()
			Flash.Impact(spot, spears.Flash)
			Shockwave.Ground(spot, spears.Ring)
		end)
		task.wait(spears.Interval)
	end
	-- 5. The pillar fades by itself; Lighting is restored by the delay above.
end

-- Typed export: the checker verifies this module matches Types.SpellModule.
local module: Types.SpellModule = { Play = CelestialVerdict.Play }
return module
]=])
make("ModuleScript", "FrostRequiem", i3, [=[
--!strict
--[[
	FrostRequiem (key 6, accent: pale cyan)
	=======================================
	1. Sharp crystal spikes burst out of the ground one after another in a
	   line from the caster to the target. Each spike is a glassy pale-cyan
	   part; a single Highlight on the spike Model gives them all a white
	   rim glow (one Highlight keeps us far below the engine's limit).
	   Frost mist and snow roll along the floor at every spike.
	2. Impact at the target: white shard particles shatter outward, a white
	   flash and ring, and a frozen star-pattern crack decal spreads.
	3. After ShatterDelay seconds every spike shatters into tumbling glass
	   fragments and is destroyed.

	Boss-tier layers: a crown of giant crystals erupts at the target, ice
	rocks burst up in a ring, a blizzard swirls over the impact, and the
	hit adds impact frames, focus lines, an FOV punch and a white core
	inside a pale-cyan ForceField shell. The shatter sends out a cyan ring.
]]

local Config = require(script.Parent.Parent.Config)
local Util = script.Parent.Parent.Util
local CameraShake = require(Util.CameraShake)
local Debris = require(Util.Debris)
local Emit = require(Util.Emit)
local Flash = require(Util.Flash)
local FocusLines = require(Util.FocusLines)
local GroundDecal = require(Util.GroundDecal)
local ImpactFrame = require(Util.ImpactFrame)
local RockRing = require(Util.RockRing)
local Shockwave = require(Util.Shockwave)
local Sphere = require(Util.Sphere)
local Types = require(Util.Types)

local C = Config.Spells.FrostRequiem.VFX
local Padding = Config.General.CleanupPadding

local FrostRequiem = {}

type Spike = { Part: Part, Base: Vector3 }

-- Grows one crystal from under the ground at `base` with the given shape.
local function growCrystal(
	model: Model,
	base: CFrame,
	height: number,
	width: number,
	orientation: CFrame,
	growTime: number
): Spike
	local spike = Emit.part(Vector3.new(width, height, width), C.SpikeColor, C.SpikeMaterial)
	spike.Name = "FrostSpike"
	spike.Transparency = C.SpikeTransparency
	local buried = base * orientation * CFrame.new(0, -height / 2, 0)
	local grown = base * orientation * CFrame.new(0, height * (0.5 - C.SpikeBury), 0)
	spike.CFrame = buried
	spike.Parent = model
	Emit.tween(spike, growTime, { CFrame = grown }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)

	local position = base.Position
	Emit.burstAt(CFrame.new(position), C.Mist)
	Emit.burstAt(CFrame.new(position), C.Snow)
	return { Part = spike, Base = position }
end

local function growSpike(model: Model, base: CFrame, scale: number): Spike
	local height = Emit.random(C.SpikeHeightMin, C.SpikeHeightMax) * scale
	local width = Emit.random(C.SpikeWidthMin, C.SpikeWidthMax) * scale
	local tilt = math.rad(C.SpikeTiltMax)
	-- Diamond cross-section (45 deg yaw) with a random lean.
	local orientation = CFrame.Angles(
		Emit.random(-tilt, tilt),
		math.rad(C.SpikeBaseYaw) + Emit.random(0, math.pi),
		Emit.random(-tilt, tilt)
	)
	return growCrystal(model, base, height, width, orientation, C.SpikeGrowTime)
end

-- Crown of giant crystals leaning outward around `center`.
local function growCluster(model: Model, center: Vector3, spikes: { Spike })
	local cluster = C.Cluster
	for i = 1, cluster.Count do
		local angle = (i / cluster.Count) * math.pi * 2 + Emit.random(-cluster.AngleJitter, cluster.AngleJitter)
		local outward = Vector3.new(math.cos(angle), 0, math.sin(angle))
		local point = Emit.groundAt(center + outward * cluster.Radius)
		local axis = Vector3.yAxis:Cross(outward).Unit
		local lean = CFrame.fromAxisAngle(axis, math.rad(Emit.random(cluster.TiltMin, cluster.TiltMax)))
		local orientation = lean * CFrame.Angles(0, math.rad(C.SpikeBaseYaw) + Emit.random(0, math.pi), 0)
		local height = Emit.random(cluster.HeightMin, cluster.HeightMax)
		local width = Emit.random(cluster.WidthMin, cluster.WidthMax)
		task.delay((i - 1) * cluster.Stagger, function()
			if model.Parent then
				table.insert(
					spikes,
					growCrystal(model, CFrame.new(point), height, width, orientation, cluster.GrowTime)
				)
			end
		end)
	end
end

function FrostRequiem.Play(character: Model, targetPosition: Vector3)
	local root = Emit.root(character)
	if root == nil then
		return
	end
	local startGround = Emit.groundAt(root.Position)
	local endGround = Emit.groundAt(targetPosition)
	local flatDelta = (endGround - startGround) * Vector3.new(1, 0, 1)
	local distance = flatDelta.Magnitude
	local direction = if distance > 1e-3 then flatDelta.Unit else root.CFrame.LookVector
	local side = direction:Cross(Vector3.yAxis)

	local count = math.clamp(math.floor((distance - C.StartGap) / C.SpikeSpacing) + 1, 1, C.MaxSpikes)
	local lifetime = count * C.SpikeInterval + C.ShatterDelay + Padding

	local model = Instance.new("Model")
	model.Name = "FrostRequiem"
	model.Parent = Emit.folder()
	Emit.cleanup(model, lifetime + C.Fragments.RiseTime)

	local rim = Instance.new("Highlight")
	rim.Adornee = model
	rim.DepthMode = Enum.HighlightDepthMode.Occluded
	rim.OutlineColor = C.RimColor
	rim.OutlineTransparency = C.RimTransparency
	rim.FillColor = C.RimFillColor
	rim.FillTransparency = C.RimFillTransparency
	rim.Parent = model

	CameraShake.Preset(C.Shake, root.Position)

	-------------------------------------------------------------------
	-- 1. Spikes erupt along the line.
	-------------------------------------------------------------------
	local spikes: { Spike } = {}
	for i = 1, count do
		local isLast = i == count
		local along = if isLast then distance else math.min(C.StartGap + (i - 1) * C.SpikeSpacing, distance)
		local jitter = if isLast then 0 else Emit.random(-C.SpikeSideJitter, C.SpikeSideJitter)
		local point = Emit.groundAt(startGround + direction * along + side * jitter)
		local scale = if isLast then C.FinalSpikeScale else 1
		table.insert(spikes, growSpike(model, CFrame.new(point), scale))
		task.wait(C.SpikeInterval)
		if not model.Parent then
			return
		end
	end

	-------------------------------------------------------------------
	-- 2. Impact at the target.
	-------------------------------------------------------------------
	local impact = endGround + Vector3.yAxis * C.SpikeHeightMin
	Flash.Impact(impact, C.Flash)
	Emit.burstAt(CFrame.new(impact), C.ImpactShatter)
	Shockwave.Ground(endGround, C.Ring)
	GroundDecal.Spawn(endGround, C.Decal)
	CameraShake.Preset(C.ImpactShake, endGround)

	-- Boss-tier layers.
	growCluster(model, endGround, spikes)
	ImpactFrame.Preset(C.Impact, impact)
	FocusLines.Play(impact, C.Focus)
	CameraShake.PunchPreset(C.Punch, impact)
	Sphere.Layers(impact, C.Spheres)
	RockRing.Ring(endGround, C.IceRocks)
	local blizzard = C.Blizzard
	local stormSize = Vector3.new(blizzard.Radius * 2, Config.General.AnchorSize.Y, blizzard.Radius * 2)
	local storm = Emit.anchor(CFrame.new(endGround), blizzard.Duration + blizzard.Spec.Lifetime.Max, stormSize)
	Emit.pulse(Emit.emitter(storm, blizzard.Spec), blizzard.Count, blizzard.Interval, blizzard.Duration)

	-------------------------------------------------------------------
	-- 3. Spikes shatter.
	-------------------------------------------------------------------
	task.wait(C.ShatterDelay)
	if not model.Parent then
		return
	end
	for _, spike in spikes do
		if spike.Part.Parent then
			local fragments = table.clone(C.Fragments)
			fragments.StartRadius = math.max(spike.Part.Size.X, C.Fragments.StartRadius)
			Debris.Shards(spike.Base, fragments)
			Emit.burstAt(spike.Part.CFrame, { Spec = C.Snow.Spec, Count = C.ShatterSnow })
			spike.Part:Destroy()
		end
	end
	Shockwave.Ground(endGround, C.ShatterRing)
	rim:Destroy()
	model:Destroy()
end

-- Typed export: the checker verifies this module matches Types.SpellModule.
local module: Types.SpellModule = { Play = FrostRequiem.Play }
return module
]=])
make("ModuleScript", "GaleReaper", i3, [=[
--!strict
--[[
	GaleReaper (key 7)
	==================
	A fast crescent wind slash fired forward.

	The blade is built from curved Beams: each half of the crescent is a
	Bezier beam from a tip (attachment axis pointing forward) to the centre
	(attachment axis pointing sideways), so the halves meet smoothly. Three
	layers are stacked: a hot white core, a soft white glow and wider
	black smoky edges set slightly behind. Tip Trails, speed-line
	particles, ink wisps and two spiralling wind trails ride along.

	On contact it splits into smaller fading crescents, kicks up dust and
	debris, and carves a long slash-shaped crack decal along its path.

	Boss-tier layers: Slashes.Count crescents fire in quick succession at
	alternating angles on parallel paths. Rocks erupt along both sides of
	the slash line, and the final hit adds impact frames, focus lines, an
	FOV punch and a white core inside a black ForceField shell.
]]

local Config = require(script.Parent.Parent.Config)
local Util = script.Parent.Parent.Util
local CameraShake = require(Util.CameraShake)
local Debris = require(Util.Debris)
local Emit = require(Util.Emit)
local Flash = require(Util.Flash)
local FocusLines = require(Util.FocusLines)
local GroundDecal = require(Util.GroundDecal)
local ImpactFrame = require(Util.ImpactFrame)
local OrbitTrail = require(Util.OrbitTrail)
local RockRing = require(Util.RockRing)
local Sphere = require(Util.Sphere)
local Types = require(Util.Types)

local C = Config.Spells.GaleReaper.VFX
local B = C.Blade

local GaleReaper = {}

type Crescent = {
	Host: Part,
	Beams: { Beam },
	Trails: { Trail },
	BaseTransparency: { number },
}

-- Attachment orientation whose X axis (the Beam curve axis) points along `axis`.
local function axisFrame(position: Vector3, axis: Vector3): CFrame
	local up = if math.abs(axis:Dot(Vector3.yAxis)) > Config.Lightning.MinPerpendicularCheck
		then Vector3.zAxis
		else Vector3.yAxis
	return CFrame.fromMatrix(position, axis, up)
end

local function buildCrescent(scale: number): Crescent
	local host = Emit.anchor(CFrame.identity, nil, C.SpeedLines.BoxSize * scale)
	local beams: { Beam } = {}
	local baseTransparency: { number } = {}
	local forward = Vector3.new(0, 0, -1) -- host-local forward
	local right = Vector3.xAxis
	local hasTexture = Config.Textures.Crescent ~= Config.PlaceholderTexture

	local function layer(
		zOffset: number,
		width: number,
		color: Color3,
		lightEmission: number,
		brightness: number,
		transparency: number
	)
		local hw = B.HalfWidth * scale
		local curve = B.Curve * scale
		local tangent = hw * B.CenterTangentScale
		local left = Emit.attachment(host, axisFrame(Vector3.new(-hw, 0, zOffset), forward))
		local center = Emit.attachment(host, axisFrame(Vector3.new(0, 0, zOffset - curve), right))
		local rightTip = Emit.attachment(host, axisFrame(Vector3.new(hw, 0, zOffset), forward))
		type Half = { A0: Attachment, A1: Attachment, Curve0: number, Curve1: number, W0: number, W1: number }
		local halves: { Half } = {
			-- tip -> centre: bulge forward at the tip, flatten sideways at the centre
			{ A0 = left, A1 = center, Curve0 = curve, Curve1 = tangent, W0 = 0, W1 = width },
			-- centre -> tip: mirror of the first half
			{ A0 = center, A1 = rightTip, Curve0 = tangent, Curve1 = -curve, W0 = width, W1 = 0 },
		}
		for _, half in halves do
			local beam = Instance.new("Beam")
			beam.Attachment0 = half.A0
			beam.Attachment1 = half.A1
			beam.CurveSize0 = half.Curve0
			beam.CurveSize1 = half.Curve1
			beam.Width0 = half.W0 * scale
			beam.Width1 = half.W1 * scale
			beam.Color = ColorSequence.new(color)
			beam.LightEmission = lightEmission
			beam.LightInfluence = 0
			beam.Brightness = brightness
			beam.FaceCamera = true
			beam.Segments = B.Segments
			beam.Transparency = NumberSequence.new(transparency)
			if hasTexture then
				beam.Texture = Config.Textures.Crescent
				beam.TextureMode = Enum.TextureMode.Stretch
			end
			beam.Parent = host
			table.insert(beams, beam)
			table.insert(baseTransparency, transparency)
		end
		return left, rightTip
	end

	-- Back to front: black smoky edges, soft glow, hot core.
	layer(B.EdgeOffset * scale, B.EdgeWidth, B.EdgeColor, 0, B.EdgeBrightness, B.EdgeTransparency)
	layer(0, B.GlowWidth, B.CoreColor, 1, B.CoreBrightness, B.GlowTransparency)
	local leftTip, rightTip = layer(0, B.CoreWidth, B.CoreColor, 1, B.CoreBrightness, 0)

	-- Tip trails.
	local trails: { Trail } = {}
	for _, tip in { leftTip, rightTip } do
		local inward = Emit.attachment(host, CFrame.new(tip.Position * (1 - B.TrailWidth / B.HalfWidth)))
		local trail = Instance.new("Trail")
		trail.Attachment0 = tip
		trail.Attachment1 = inward
		trail.Lifetime = B.TrailLifetime
		trail.Color = ColorSequence.new(B.CoreColor)
		trail.Transparency = NumberSequence.new(0, 1)
		trail.LightEmission = 1
		trail.LightInfluence = 0
		trail.Brightness = B.CoreBrightness
		trail.FaceCamera = true
		trail.Enabled = false
		trail.Parent = host
		table.insert(trails, trail)
	end

	return { Host = host, Beams = beams, Trails = trails, BaseTransparency = baseTransparency }
end

-- Moves a crescent from `from` along `direction` for `distance` studs over
-- `duration` seconds. When `fade` is set the blade fades out as it goes.
-- `onArrive` runs when it reaches the end (not if destroyed early).
local function launch(
	crescent: Crescent,
	from: Vector3,
	direction: Vector3,
	distance: number,
	duration: number,
	fade: boolean,
	rollDegrees: number,
	onArrive: (() -> ())?
)
	local host = crescent.Host
	local roll = CFrame.Angles(0, 0, math.rad(rollDegrees))
	local function place(alpha: number)
		local position = from + direction * distance * alpha
		host.CFrame = CFrame.lookAt(position, position + direction) * roll
	end
	place(0)
	for _, trail in crescent.Trails do
		trail.Enabled = true
	end

	Emit.step(duration, function(alpha)
		if not host.Parent then
			return true
		end
		place(alpha)
		if fade then
			for i, beam in crescent.Beams do
				local base = crescent.BaseTransparency[i]
				beam.Transparency = NumberSequence.new(base + (1 - base) * alpha)
			end
		end
		return false
	end, function()
		if not host.Parent then
			return
		end
		for _, beam in crescent.Beams do
			beam.Enabled = false
		end
		for _, trail in crescent.Trails do
			trail.Enabled = false
		end
		-- Keep the host until the trails and particles have faded.
		Emit.cleanup(host, math.max(B.TrailLifetime, C.SpeedLines.Spec.Lifetime.Max, C.WakeSmoke.Spec.Lifetime.Max))
		if onArrive then
			onArrive()
		end
	end)
end

function GaleReaper.Play(character: Model, targetPosition: Vector3)
	local root = Emit.root(character)
	if root == nil then
		return
	end
	local start = (root.CFrame * CFrame.new(C.LaunchOffset)).Position
	local finish = Emit.groundAt(targetPosition) + Vector3.yAxis * C.BladeHeight
	local delta = finish - start
	local distance = delta.Magnitude
	local direction = if distance > 1e-3 then delta.Unit else root.CFrame.LookVector
	local travelTime = math.max(distance / C.Speed, C.MinTravelTime)

	local side = direction:Cross(Vector3.yAxis)
	side = if side.Magnitude > 1e-3 then side.Unit else root.CFrame.RightVector
	local flat = Vector3.new(direction.X, 0, direction.Z)
	local flatDirection = if flat.Magnitude > 1e-3 then flat.Unit else root.CFrame.LookVector
	local slashes = C.Slashes

	local spiralStyle: Types.TrailStyle = {
		Width = C.Spirals.Width,
		Lifetime = C.Spirals.Lifetime,
		Color = C.Spirals.Color,
		Transparency = C.Spirals.Transparency,
		LightEmission = C.Spirals.LightEmission,
		Brightness = C.Spirals.Brightness,
	}
	local axisTurn = CFrame.Angles(math.pi / 2, 0, 0) -- orbit plane perpendicular to travel

	local function fireSlash(index: number)
		local isFinal = index == slashes.Count
		local offset = side * ((index - (slashes.Count + 1) / 2) * slashes.SideOffset)
		local from = start + offset
		local to = finish + offset
		local roll = slashes.Rolls[((index - 1) % #slashes.Rolls) + 1]

		local blade = buildCrescent(1)
		local speedLines = Emit.emitter(blade.Host, C.SpeedLines.Spec)
		local wake = Emit.emitter(blade.Host, C.WakeSmoke.Spec)
		Emit.pulse(speedLines, C.SpeedLines.Count, C.SpeedLines.Interval, travelTime)
		Emit.pulse(wake, C.WakeSmoke.Count, C.SpeedLines.Interval, travelTime)

		-- Wind spirals wrapping the travel axis.
		for i = 1, C.Spirals.Count do
			OrbitTrail.Start(function(): CFrame?
				if not blade.Host.Parent then
					return nil
				end
				return blade.Host.CFrame * axisTurn
			end, {
				Radius = C.Spirals.Radius,
				Height = 0,
				Speed = C.Spirals.Speed,
				Tilt = Vector3.zero,
				Phase = (i / C.Spirals.Count) * math.pi * 2,
			}, spiralStyle, travelTime)
		end

		launch(blade, from, direction, distance, travelTime, false, roll, function()
			local ground = Emit.groundAt(to)

			-- Split into smaller crescents fanning outward.
			local spread = math.rad(C.Split.SpreadDegrees)
			for i = 1, C.Split.Count do
				local t = if C.Split.Count > 1 then (i - 1) / (C.Split.Count - 1) else 0.5
				local yaw = CFrame.Angles(0, -spread / 2 + spread * t, 0)
				local splitDirection = (yaw * direction).Unit
				launch(
					buildCrescent(C.Split.Scale),
					to,
					splitDirection,
					C.Split.Distance,
					C.Split.Duration,
					true,
					roll,
					nil
				)
			end

			Flash.Impact(to, C.Flash)
			Emit.burstAt(CFrame.new(ground), C.Dust)
			Debris.Shards(ground, C.Shards)
			-- The slash decal is centred half its length back along the path.
			local slashLength = C.Decal.Length or C.Decal.Radius * 2
			local decalCenter = ground - flatDirection * (slashLength / 2)
			GroundDecal.Spawn(decalCenter, C.Decal, flatDirection)
			CameraShake.Preset(C.Shake, ground)

			if isFinal then
				ImpactFrame.Preset(C.Impact, to)
				FocusLines.Play(to, C.Focus)
				CameraShake.PunchPreset(C.Punch, to)
				Sphere.Layers(to, C.Spheres)
				RockRing.Line(Emit.groundAt(start), ground, C.PathRocks)
			end
		end)
	end

	for index = 1, slashes.Count do
		fireSlash(index)
		if index < slashes.Count then
			task.wait(slashes.Interval)
		end
	end
end

-- Typed export: the checker verifies this module matches Types.SpellModule.
local module: Types.SpellModule = { Play = GaleReaper.Play }
return module
]=])
make("ModuleScript", "GrimoireAwakening", i3, [=[
--!strict
--[[
	GrimoireAwakening (key 1, summon)
	=================================
	The caster's grimoire materialises above their open hand:
	  1. Black ink pages spiral out of nothing (plus inward ink wisps) and
	     snap together into a floating book.
	  2. White runes etch across the cover as flickering electric lines.
	  3. The cover flips open with a white flash and spark burst.
	  4. A ring of glowing glyph tiles spins slowly at waist height while two
	     white trails orbit the caster for Orbit.Duration seconds.
	  5. The open book settles into a faint idle glow, then fades away.

	Boss-tier layers: the book opening fires impact frames, focus lines, an
	FOV punch, a white ring and a white core inside a black ForceField
	shell. During the glyph phase white arcs jump between neighbouring
	glyphs, an ink storm swirls up around the caster and white motes rise
	out of the ring.

	The book follows the caster's hand every frame. Everything is parented
	to one Folder that is destroyed at the end (and scheduled with Debris as
	a safety net), so repeated casts never leak.
]]

local Config = require(script.Parent.Parent.Config)
local Util = script.Parent.Parent.Util
local Emit = require(Util.Emit)
local CameraShake = require(Util.CameraShake)
local Flash = require(Util.Flash)
local FocusLines = require(Util.FocusLines)
local ImpactFrame = require(Util.ImpactFrame)
local Lightning = require(Util.Lightning)
local OrbitTrail = require(Util.OrbitTrail)
local Shockwave = require(Util.Shockwave)
local Sphere = require(Util.Sphere)
local Types = require(Util.Types)

local C = Config.Spells.GrimoireAwakening.VFX
local Padding = Config.General.CleanupPadding

local GrimoireAwakening = {}

local function handPosition(character: Model, root: BasePart): Vector3
	for _, name in C.HandNames do
		local hand = character:FindFirstChild(name)
		if hand and hand:IsA("BasePart") then
			return hand.Position
		end
	end
	return (root.CFrame * CFrame.new(C.FallbackOffset)).Position
end

local function totalDuration(): number
	return C.GatherTime
		+ C.SnapTime
		+ #C.RuneLines * C.RuneEtchInterval
		+ C.RuneHoldTime
		+ C.OpenTime
		+ C.Orbit.Duration
		+ C.IdleTime
		+ C.FadeTime
end

function GrimoireAwakening.Play(character: Model, _targetPosition: Vector3)
	local root = Emit.root(character)
	if root == nil then
		return
	end

	local group = Instance.new("Folder")
	group.Name = "GrimoireAwakening"
	group.Parent = Emit.folder()
	Emit.cleanup(group, totalDuration() + Padding)

	-- Book placement: above the hand, oriented with the character.
	local lastBookCFrame = CFrame.new(handPosition(character, root)) * root.CFrame.Rotation * CFrame.new(C.BookOffset)
	local bob = 0
	local function bookCFrame(): CFrame
		local currentRoot = Emit.root(character)
		if currentRoot and character.Parent then
			lastBookCFrame = CFrame.new(handPosition(character, currentRoot))
				* currentRoot.CFrame.Rotation
				* CFrame.new(C.BookOffset)
		end
		return lastBookCFrame * CFrame.new(0, bob, 0)
	end

	-------------------------------------------------------------------
	-- 1. Pages spiral in from nothing.
	-------------------------------------------------------------------
	local start = bookCFrame()
	local wispHost = Emit.anchor(start, C.InkGather.Spec.Lifetime.Max, Vector3.one * C.InkGather.Radius * 2)
	Emit.emitter(wispHost, C.InkGather.Spec):Emit(C.InkGather.Count)

	type Page = { Part: Part, Angle: number, Height: number, Tumble: Vector3 }
	local pages: { Page } = {}
	for i = 1, C.PageCount do
		local page = Emit.part(C.PageSize, C.PageColor, C.PageMaterial)
		page.Name = "Page"
		page.Transparency = 1
		page.Parent = group
		Emit.tween(page, C.PageFadeIn, { Transparency = 0 })
		table.insert(pages, {
			Part = page,
			Angle = (i / C.PageCount) * math.pi * 2,
			Height = Emit.random(-C.PageStartHeight, C.PageStartHeight),
			Tumble = Emit.randomUnit() * C.PageTumble,
		})
	end

	local function placePages(alpha: number)
		local eased = 1 - (1 - alpha) ^ 3
		local center = bookCFrame()
		for i, page in pages do
			local radius = C.PageStartRadius * (1 - eased)
			local angle = page.Angle + C.PageSpinTurns * math.pi * 2 * eased
			local height = page.Height * (1 - eased) + (i - 1) * C.PageStackGap
			local tumble = page.Tumble * (1 - eased)
			page.Part.CFrame = center
				* CFrame.new(math.cos(angle) * radius, height, math.sin(angle) * radius)
				* CFrame.Angles(tumble.X, angle + tumble.Y, tumble.Z)
		end
	end
	placePages(0)
	Emit.step(C.GatherTime, function(alpha)
		if not group.Parent then
			return true
		end
		placePages(alpha)
		return false
	end)
	task.wait(C.GatherTime)
	if not group.Parent then
		return
	end
	for _, page in pages do
		page.Part:Destroy()
	end

	-------------------------------------------------------------------
	-- 2. Book forms (block + hinged cover) and snaps into place.
	-------------------------------------------------------------------
	local block = Emit.part(C.BookSize, C.PageColor, C.PageMaterial)
	block.Name = "Book"
	block.Parent = group
	local coverSize = Vector3.new(C.BookSize.X, C.CoverThickness, C.BookSize.Z)
	local cover = Emit.part(coverSize, C.CoverColor, C.CoverMaterial)
	cover.Name = "Cover"
	cover.Parent = group

	local light = Instance.new("PointLight")
	light.Color = C.IdleLight.Color
	light.Brightness = 0
	light.Range = C.IdleLight.Range
	light.Shadows = false
	light.Parent = block

	local coverAngle = 0
	local scale = C.SnapScale
	local function coverCFrame(): CFrame
		-- Hinge along the spine (local -X edge of the book's top face).
		local book = bookCFrame()
		local halfX = C.BookSize.X / 2
		local top = C.BookSize.Y / 2 + C.CoverThickness / 2
		return book * CFrame.new(-halfX, top, 0) * CFrame.Angles(0, 0, coverAngle) * CFrame.new(halfX, 0, 0)
	end

	local idleTime = 0
	local followDuration = totalDuration() - C.GatherTime
	Emit.step(followDuration, function(_alpha, dt, elapsed)
		if not group.Parent then
			return true
		end
		if elapsed > followDuration - C.FadeTime - C.IdleTime then
			idleTime += dt
			bob = math.sin(idleTime * C.IdleBobSpeed) * C.IdleBobAmplitude
		end
		block.Size = C.BookSize * scale
		cover.Size = coverSize * scale
		block.CFrame = bookCFrame()
		cover.CFrame = coverCFrame()
		return false
	end)

	-- Snap: pop to SnapScale then settle to 1.
	local snapValue = Instance.new("NumberValue")
	snapValue.Value = C.SnapScale
	snapValue.Changed:Connect(function(value: number)
		scale = value
	end)
	local snap = Emit.tween(snapValue, C.SnapTime, { Value = 1 }, Enum.EasingStyle.Back)
	snap.Completed:Once(function()
		snapValue:Destroy()
	end)
	task.wait(C.SnapTime)
	if not group.Parent then
		return
	end

	-------------------------------------------------------------------
	-- 3. Runes etch across the cover as electric lines.
	-------------------------------------------------------------------
	local runeLift = C.CoverThickness / 2 + C.RuneHeight
	local function coverPoint(p: Vector2): Vector3
		return (coverCFrame() * CFrame.new(p.X * C.BookSize.X / 2, runeLift, p.Y * C.BookSize.Z / 2)).Position
	end
	local runeHandles: { Types.Handle } = {}
	local remainingEtch = #C.RuneLines * C.RuneEtchInterval + C.RuneHoldTime
	for index, line in C.RuneLines do
		local params = table.clone(C.RuneBolt)
		-- Every line lives until the book opens, however late it was etched.
		params.Duration = remainingEtch - (index - 1) * C.RuneEtchInterval
		table.insert(
			runeHandles,
			Lightning.Bolt(function()
				return coverPoint(line[1]), coverPoint(line[2])
			end, params)
		)
		task.wait(C.RuneEtchInterval)
	end
	task.wait(C.RuneHoldTime)
	if not group.Parent then
		return
	end

	-------------------------------------------------------------------
	-- 4. The cover flips open with a white flash.
	-------------------------------------------------------------------
	Emit.step(C.OpenTime, function(alpha)
		coverAngle = math.pi * (1 - (1 - alpha) ^ 2)
		return false
	end)
	task.wait(C.OpenTime)
	if not group.Parent then
		return
	end
	local openPosition = block.Position
	Flash.Impact(openPosition, C.OpenFlash)
	Emit.burstAt(CFrame.new(openPosition), { Spec = Config.Emitters.WhiteSparks, Count = C.OpenSparks })
	Emit.burstAt(CFrame.new(openPosition), { Spec = Config.Emitters.CoreFlare, Count = 1 })
	light.Brightness = C.IdleLight.Brightness
	ImpactFrame.Preset(C.OpenImpact, openPosition)
	FocusLines.Play(openPosition, C.OpenFocus)
	CameraShake.PunchPreset(C.OpenPunch, openPosition)
	CameraShake.Preset(C.OpenShake, openPosition)
	Sphere.Layers(openPosition, C.OpenSpheres)
	local feet = Emit.feet(character) or root.Position
	Shockwave.Ground(feet, C.OpenRing)

	-------------------------------------------------------------------
	-- 5. Glyph ring at waist height + two orbiting trails.
	-------------------------------------------------------------------
	local glyphs: { Part } = {}
	local hasGlyphTexture = Config.Textures.Glyph ~= Config.PlaceholderTexture
	for _ = 1, C.GlyphCount do
		local glyph = Emit.part(C.GlyphSize, C.GlyphColor, Enum.Material.Neon)
		glyph.Name = "Glyph"
		glyph.Transparency = 1
		glyph.Parent = group
		if hasGlyphTexture then
			for _, face in { Enum.NormalId.Front, Enum.NormalId.Back } do
				local decal = Instance.new("Decal")
				decal.Texture = Config.Textures.Glyph
				decal.Face = face
				decal.Parent = glyph
			end
		end
		Emit.tween(glyph, C.GlyphFadeIn, { Transparency = C.GlyphTransparency })
		table.insert(glyphs, glyph)
	end
	local glyphAngle = 0
	local glyphCenter = CFrame.new(root.Position)

	-- Ink storm + rising motes on a cylinder host that follows the caster.
	local storm = C.InkStorm
	local stormSize = Vector3.new(storm.Radius * 2, storm.Height, storm.Radius * 2)
	local stormHost = Emit.anchor(CFrame.new(feet), nil, stormSize)
	stormHost.Parent = group
	Emit.pulse(Emit.emitter(stormHost, storm.Spec), storm.Count, storm.Interval, C.Orbit.Duration)
	Emit.pulse(
		Emit.emitter(stormHost, C.RisingRunes.Spec),
		C.RisingRunes.Count,
		C.RisingRunes.Interval,
		C.Orbit.Duration
	)
	local webTimer = 0

	Emit.step(C.Orbit.Duration + C.GlyphFadeIn, function(_alpha, dt, elapsed)
		if not group.Parent then
			return true
		end
		local currentRoot = Emit.root(character)
		if currentRoot then
			glyphCenter = CFrame.new(currentRoot.Position)
			stormHost.CFrame = CFrame.new(Emit.feet(character) or currentRoot.Position)
		end
		-- Arcs jumping between neighbouring glyphs.
		webTimer += dt
		if webTimer >= C.GlyphWeb.Interval and elapsed < C.Orbit.Duration and #glyphs > 1 then
			webTimer = 0
			local i = Emit.randomInt(1, #glyphs)
			local a, b = glyphs[i], glyphs[(i % #glyphs) + 1]
			Lightning.Strike(a.Position, b.Position, C.GlyphWeb.Bolt)
		end
		glyphAngle += C.GlyphSpinSpeed * dt
		for i, glyph in glyphs do
			local a = glyphAngle + (i / #glyphs) * math.pi * 2
			local bobOffset = math.sin(elapsed * C.GlyphBobSpeed + i) * C.GlyphBobAmplitude
			local offset =
				Vector3.new(math.cos(a) * C.GlyphRadius, C.GlyphHeight + bobOffset, math.sin(a) * C.GlyphRadius)
			local position = glyphCenter.Position + offset
			glyph.CFrame = CFrame.lookAt(position, glyphCenter.Position + Vector3.yAxis * offset.Y)
		end
		return false
	end)

	local style: Types.TrailStyle = {
		Width = C.Orbit.Width,
		Lifetime = C.Orbit.Lifetime,
		Color = C.Orbit.Color,
		Transparency = C.Orbit.Transparency,
		LightEmission = C.Orbit.LightEmission,
		Brightness = C.Orbit.Brightness,
	}
	for _, orbit in C.Orbit.Trails do
		OrbitTrail.OnCharacter(character, orbit, style, C.Orbit.Duration)
	end
	task.wait(C.Orbit.Duration)
	if not group.Parent then
		return
	end
	for _, glyph in glyphs do
		Emit.tween(glyph, C.GlyphFadeIn, { Transparency = 1 })
	end

	-------------------------------------------------------------------
	-- 6. Faint idle glow, then fade everything out.
	-------------------------------------------------------------------
	task.wait(C.IdleTime)
	if not group.Parent then
		return
	end
	Emit.tween(light, C.FadeTime, { Brightness = 0 })
	Emit.tween(block, C.FadeTime, { Transparency = 1 })
	Emit.tween(cover, C.FadeTime, { Transparency = 1 })
	Emit.cleanup(group, C.FadeTime)
	for _, handle in runeHandles do
		handle.Stop()
	end
end

-- Typed export: the checker verifies this module matches Types.SpellModule.
local module: Types.SpellModule = { Play = GrimoireAwakening.Play }
return module
]=])
make("ModuleScript", "InfernoSeal", i3, [=[
--!strict
--[[
	InfernoSeal (key 5, accent: deep crimson)
	=========================================
	1. A circular rune seal draws itself on the ground in white lines.
	2. A pillar of black and crimson flames erupts upward with embers,
	   flickering smoke and a flickering crimson PointLight.
	3. Ends with a white flash core and a shockwave ring, leaving glowing
	   embers drifting off a cracked ground decal with crimson ember cracks.

	Boss-tier layers: crimson flames lick up along the seal's edge while it
	draws; the eruption tears a ring of basalt rocks out of the ground with
	an FOV punch, and crimson + black flame ribbons coil up the pillar.
	The finale adds impact frames, focus lines and a white core sphere in a
	crimson ForceField shell.

	Crimson is only used for flames, embers, light, crack glow and the
	finale's outer shell.
]]

local Config = require(script.Parent.Parent.Config)
local Util = script.Parent.Parent.Util
local CameraShake = require(Util.CameraShake)
local Emit = require(Util.Emit)
local Flash = require(Util.Flash)
local FocusLines = require(Util.FocusLines)
local GroundDecal = require(Util.GroundDecal)
local ImpactFrame = require(Util.ImpactFrame)
local OrbitTrail = require(Util.OrbitTrail)
local RockRing = require(Util.RockRing)
local RuneCircle = require(Util.RuneCircle)
local Shockwave = require(Util.Shockwave)
local Sphere = require(Util.Sphere)
local Types = require(Util.Types)

local C = Config.Spells.InfernoSeal.VFX

local InfernoSeal = {}

function InfernoSeal.Play(_character: Model, targetPosition: Vector3)
	local groundCFrame = Emit.groundCFrame(targetPosition)
	local ground = groundCFrame.Position

	-------------------------------------------------------------------
	-- 1. Seal draws itself.
	-------------------------------------------------------------------
	RuneCircle.Spawn(groundCFrame, C.Seal)
	-- Flames licking up along the seal's edge for its whole life.
	local ringLife = C.Seal.DrawTime + C.Seal.Hold
	local ringSize = Vector3.new(C.Seal.Radius * 2, Config.General.AnchorSize.Y, C.Seal.Radius * 2)
	local ringHost = Emit.anchor(groundCFrame, ringLife + C.FireRing.Spec.Lifetime.Max, ringSize)
	Emit.pulse(Emit.emitter(ringHost, C.FireRing.Spec), C.FireRing.Count, C.FireRing.Interval, ringLife)
	task.wait(C.Seal.DrawTime)

	-------------------------------------------------------------------
	-- 2. Flame pillar.
	-------------------------------------------------------------------
	local longestParticle = math.max(
		C.BlackFlames.Spec.Lifetime.Max,
		C.CrimsonFlames.Spec.Lifetime.Max,
		C.Embers.Spec.Lifetime.Max,
		C.FlickerSmoke.Spec.Lifetime.Max
	)
	local pillarSize = Vector3.new(C.PillarRadius * 2, C.PillarHeight, C.PillarRadius * 2)
	local pillar =
		Emit.anchor(groundCFrame * CFrame.new(0, C.PillarHeight / 2, 0), C.PillarDuration + longestParticle, pillarSize)

	for _, burst in { C.BlackFlames, C.CrimsonFlames, C.Embers, C.FlickerSmoke } do
		local emitter = Emit.emitter(pillar, burst.Spec)
		Emit.pulse(emitter, burst.Count, C.PulseInterval, C.PillarDuration)
	end

	-- Eruption: rocks + FOV punch + coiling flame ribbons.
	RockRing.Ring(ground, C.EruptRocks)
	CameraShake.PunchPreset(C.EruptPunch, ground)
	CameraShake.Preset(C.EruptShake, ground)
	local spiral = C.Spirals
	local flameStyle: Types.TrailStyle = {
		Width = spiral.Width,
		Lifetime = spiral.Lifetime,
		Color = spiral.Color,
		Transparency = spiral.Transparency,
		LightEmission = spiral.LightEmission,
		Brightness = spiral.Brightness,
	}
	local inkStyle: Types.TrailStyle = {
		Width = spiral.InkWidth,
		Lifetime = spiral.Lifetime,
		Color = Config.Palette.Black,
		Transparency = spiral.Transparency,
		LightEmission = 0,
		Brightness = spiral.InkBrightness,
	}
	local center = CFrame.new(ground)
	for i = 1, spiral.Count do
		local phase = (i / spiral.Count) * math.pi * 2
		type Ribbon = { Style: Types.TrailStyle, PhaseOffset: number }
		local ribbons: { Ribbon } = {
			{ Style = flameStyle, PhaseOffset = 0 },
			{ Style = inkStyle, PhaseOffset = math.pi / spiral.Count }, -- black ribbons sit between the flames
		}
		for _, ribbon in ribbons do
			OrbitTrail.Start(function(): CFrame?
				return center
			end, {
				Radius = spiral.Radius,
				Height = 0,
				Speed = spiral.Speed,
				Tilt = Vector3.zero,
				Phase = phase + ribbon.PhaseOffset,
				RiseSpeed = spiral.RiseSpeed,
			}, ribbon.Style, C.PillarDuration)
		end
	end

	local light = Instance.new("PointLight")
	light.Color = C.PillarLight.Color
	light.Brightness = C.PillarLight.Brightness
	light.Range = C.PillarLight.Range
	light.Shadows = false
	light.Parent = pillar
	Emit.step(C.PillarDuration, function(alpha)
		if not light.Parent then
			return true
		end
		local flicker = Emit.random(C.LightFlickerMin, C.LightFlickerMax)
		light.Brightness = C.PillarLight.Brightness * flicker * (1 - alpha)
		return false
	end)

	task.wait(C.PillarDuration)

	-------------------------------------------------------------------
	-- 3. White flash core, shockwave, lingering embers on cracked ground.
	-------------------------------------------------------------------
	local core = ground + Vector3.yAxis * C.PillarHeight
	Flash.Impact(core, C.EndFlash)
	Emit.burstAt(CFrame.new(core), { Spec = Config.Emitters.CoreFlare, Count = C.EndCoreCount })
	Shockwave.Ground(ground, C.EndRing)
	GroundDecal.Spawn(ground, C.Decal)
	CameraShake.Preset(C.Shake, ground)
	ImpactFrame.Preset(C.EndImpact, core)
	FocusLines.Play(core, C.EndFocus)
	CameraShake.PunchPreset(C.EndPunch, core)
	Sphere.Layers(core, C.EndSpheres)

	local emberSize = Vector3.new(C.Decal.Radius * 2, C.PillarHeight, C.Decal.Radius * 2)
	local emberHost = Emit.anchor(groundCFrame, C.GroundEmbers.Duration + C.GroundEmbers.Spec.Lifetime.Max, emberSize)
	local embers = Emit.emitter(emberHost, C.GroundEmbers.Spec)
	Emit.pulse(embers, C.GroundEmbers.Count, C.GroundEmbers.Interval, C.GroundEmbers.Duration)
