make("ModuleScript", "CameraShake", i12, [=[
--!strict
--[[
	CameraShake
	===========
	Client-only, additive Perlin-noise camera shake. Any number of shakes can
	run at once; their offsets are summed and applied once per frame, right
	after the default camera scripts (RenderPriority.Camera + 1), so the
	camera never drifts. Strength falls off with distance from the source.
	The render step unbinds itself when the last shake ends.

	  CameraShake.Shake(Config.CameraShake.Presets.Heavy, impactPosition)
	  CameraShake.Preset("Heavy", impactPosition)
]]

local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local Config = require(script.Parent.Parent.Config)
local Types = require(script.Parent.Types)

local Settings = Config.CameraShake

type ActiveShake = {
	Magnitude: number,
	Frequency: number,
	Duration: number,
	Start: number,
	Source: Vector3?,
	Seed: number,
}

local CameraShake = {}

local active: { ActiveShake } = {}
local bound = false
local rng = Random.new()

local function distanceScale(source: Vector3?, camera: Camera): number
	if source == nil then
		return 1
	end
	local distance = (camera.CFrame.Position - source).Magnitude
	if distance <= Settings.MinDistance then
		return 1
	end
	local range = Settings.MaxDistance - Settings.MinDistance
	return math.clamp(1 - (distance - Settings.MinDistance) / range, 0, 1)
end

local function unbind()
	if bound then
		RunService:UnbindFromRenderStep(Settings.BindName)
		bound = false
	end
end

local function update()
	local camera = Workspace.CurrentCamera
	if camera == nil then
		return
	end
	local now = os.clock()
	local offset = Vector3.zero
	local rotation = Vector3.zero

	for index = #active, 1, -1 do
		local shake = active[index]
		local t = now - shake.Start
		if t >= shake.Duration then
			table.remove(active, index)
		else
			local fade = 1 - t / shake.Duration
			local strength = shake.Magnitude * fade * fade * distanceScale(shake.Source, camera)
			local n = t * shake.Frequency
			local s = shake.Seed
			offset += Vector3.new(math.noise(n, s, 0), math.noise(s, n, 0), math.noise(0, s, n)) * strength
			rotation += Vector3.new(math.noise(n, s, 1), math.noise(s, n, 1), math.noise(1, s, n)) * strength * Settings.RotationScale
		end
	end

	if #active == 0 then
		unbind()
		return
	end

	camera.CFrame = camera.CFrame
		* CFrame.new(offset)
		* CFrame.Angles(math.rad(rotation.X), math.rad(rotation.Y), math.rad(rotation.Z))
end

-- Starts a shake. `source` enables distance falloff.
function CameraShake.Shake(params: Types.ShakeParams, source: Vector3?)
	if not RunService:IsClient() then
		return
	end
	table.insert(active, {
		Magnitude = params.Magnitude,
		Frequency = params.Frequency,
		Duration = params.Duration,
		Start = os.clock(),
		Source = source,
		Seed = rng:NextNumber(0, 1000),
	})
	if not bound then
		bound = true
		RunService:BindToRenderStep(Settings.BindName, Enum.RenderPriority.Camera.Value + 1, update)
	end
end

---------------------------------------------------------------------------
-- FOV punch: the camera's field of view kicks out and eases back. Punches
-- add together; the original FOV is restored exactly when the last ends.
---------------------------------------------------------------------------
type ActivePunch = { Delta: number, InTime: number, OutTime: number, Start: number }
local punches: { ActivePunch } = {}
local baseFov: number? = nil
local punchConnection: RBXScriptConnection? = nil

local function punchOffset(punch: ActivePunch, t: number): number
	if t < punch.InTime then
		local a = t / punch.InTime
		return punch.Delta * (1 - (1 - a) ^ 3)
	end
	local a = math.clamp((t - punch.InTime) / punch.OutTime, 0, 1)
	return punch.Delta * (1 - a) ^ 2
end

function CameraShake.Punch(params: Types.PunchParams, source: Vector3?)
	local camera = Workspace.CurrentCamera
	if not RunService:IsClient() or camera == nil then
		return
	end
	local scale = distanceScale(source, camera)
	if scale <= 0 then
		return
	end
	if baseFov == nil then
		baseFov = camera.FieldOfView
	end
	table.insert(
		punches,
		{ Delta = params.FovDelta * scale, InTime = params.InTime, OutTime = params.OutTime, Start = os.clock() }
	)
	if punchConnection then
		return
	end
	punchConnection = RunService.RenderStepped:Connect(function()
		local cam = Workspace.CurrentCamera
		local base = baseFov
		if cam == nil or base == nil then
			return
		end
		local now = os.clock()
		local total = 0
		for index = #punches, 1, -1 do
			local punch = punches[index]
			local t = now - punch.Start
			if t >= punch.InTime + punch.OutTime then
				table.remove(punches, index)
			else
				total += punchOffset(punch, t)
			end
		end
		cam.FieldOfView = math.clamp(base + total, Settings.MinFov, Settings.MaxFov)
		if #punches == 0 then
			cam.FieldOfView = base
			baseFov = nil
			local connection = punchConnection
			punchConnection = nil
			if connection then
				connection:Disconnect()
			end
		end
	end)
end

function CameraShake.PunchPreset(name: string, source: Vector3?)
	local preset = (Settings.Punches :: any)[name] :: Types.PunchParams?
	if preset then
		CameraShake.Punch(preset, source)
	else
		warn("[VFX] Unknown camera punch preset:", name)
	end
end

-- Shake using a named preset from Config.CameraShake.Presets.
function CameraShake.Preset(name: string, source: Vector3?)
	local preset = (Settings.Presets :: any)[name] :: Types.ShakeParams?
	if preset then
		CameraShake.Shake(preset, source)
	else
		warn("[VFX] Unknown camera shake preset:", name)
	end
end

return CameraShake
]=])
make("ModuleScript", "Debris", i12, [=[
--!strict
--[[
	Debris (VFX)
	============
	Floating debris shards (client only). Each shard is an anchored part that:
	  1. rises (and drifts outward) from the ground with a random spin,
	  2. hangs in the air with a slow drift,
	  3. falls back down while fading out, then is destroyed.

	Phases are chained with Tween.Completed, so if a shard is destroyed
	early the chain simply stops. Debris (the Roblox service, aliased
	DebrisService here) guarantees cleanup regardless.

	  Debris.Shards(centerPosition, Config...Shards)
]]

local DebrisService = game:GetService("Debris")

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Debris = {}

local function randomRotation(maxDegrees: number): CFrame
	local r = math.rad(maxDegrees)
	return CFrame.Angles(Emit.random(-r, r), Emit.random(-r, r), Emit.random(-r, r))
end

function Debris.Shards(center: Vector3, params: Types.ShardParams)
	local ground = Emit.groundAt(center)
	local total = params.RiseTime + params.HangTime + params.FallTime + Config.General.CleanupPadding
	local folder = Emit.folder()

	for _ = 1, params.Count do
		local angle = Emit.random(0, math.pi * 2)
		local distance = Emit.random(0, params.StartRadius)
		local outward = Vector3.new(math.cos(angle), 0, math.sin(angle))
		local start = ground + outward * distance + Vector3.yAxis * Config.Debris.SpawnHeight

		local size = Vector3.new(
			Emit.random(params.SizeMin, params.SizeMax),
			Emit.random(params.SizeMin, params.SizeMax),
			Emit.random(params.SizeMin, params.SizeMax)
		)
		local shard = Emit.part(size, params.Color, params.Material)
		shard.Name = "Shard"
		shard.CFrame = CFrame.new(start) * randomRotation(params.SpinMax)
		shard.Parent = folder
		DebrisService:AddItem(shard, total)

		local risePosition = start
			+ Vector3.yAxis * Emit.random(params.RiseMin, params.RiseMax)
			+ outward * params.Spread
		local rise = Emit.tween(shard, params.RiseTime, {
			CFrame = CFrame.new(risePosition) * randomRotation(params.SpinMax),
		}, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)

		rise.Completed:Once(function(state: Enum.PlaybackState)
			if state ~= Enum.PlaybackState.Completed or not shard.Parent then
				return
			end
			local hangPosition = risePosition + Vector3.yAxis * params.HangDrift
			local hang = Emit.tween(shard, params.HangTime, {
				CFrame = CFrame.new(hangPosition) * shard.CFrame.Rotation * randomRotation(
					params.SpinMax * Config.Debris.HangSpinScale
				),
			}, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)

			hang.Completed:Once(function(hangState: Enum.PlaybackState)
				if hangState ~= Enum.PlaybackState.Completed or not shard.Parent then
					return
				end
				local fallPosition = hangPosition - Vector3.yAxis * params.FallDistance + outward * params.FallSpread
				Emit.tween(shard, params.FallTime, {
					CFrame = CFrame.new(fallPosition) * randomRotation(params.SpinMax),
					Transparency = 1,
				}, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end)
		end)
	end
end

return Debris
]=])
make("ModuleScript", "Emit", i12, [=[
--!strict
--[[
	Emit
	====
	Low-level helpers shared by every effect (client only):

	  * Emit.folder()            - the Workspace folder all VFX instances live in
	  * Emit.anchor(cf, life)    - invisible, anchored, non-colliding host part
	  * Emit.attachment(...)     - attachment builder
	  * Emit.emitter(parent, s)  - ParticleEmitter from a Types.EmitterSpec
	  * Emit.burstAt(cf, b)      - one-shot :Emit(n) burst that cleans itself up
	  * Emit.pulse(...)          - repeated :Emit(n) bursts for a duration
	  * Emit.tween / fadeSequence- TweenService helpers (always finite)
	  * Emit.step(dur, fn)       - per-frame callback that disconnects itself
	  * Emit.cleanup(inst, t)    - Debris service removal
	  * Emit.groundAt(pos)       - raycast down for ground position + normal

	Nothing here yields.
]]

local DebrisService = game:GetService("Debris")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local Workspace = game:GetService("Workspace")

local Config = require(script.Parent.Parent.Config)
local Types = require(script.Parent.Types)

local General = Config.General
local rng = Random.new()

local Emit = {}

local cachedFolder: Folder? = nil

-- Returns (and lazily creates) the client-side folder that holds all VFX.
function Emit.folder(): Folder
	local current = cachedFolder
	if current and current.Parent then
		return current
	end
	local existing = Workspace:FindFirstChild(General.FolderName)
	if existing and existing:IsA("Folder") then
		cachedFolder = existing
		return existing
	end
	local folder = Instance.new("Folder")
	folder.Name = General.FolderName
	folder.Parent = Workspace
	cachedFolder = folder
	return folder
end

-- Schedules an instance for removal (Debris never yields).
function Emit.cleanup(instance: Instance, seconds: number)
	DebrisService:AddItem(instance, seconds)
end

-- Makes a part invisible, anchored and inert to physics / raycasts.
function Emit.makeInert(part: BasePart)
	part.Anchored = true
	part.CanCollide = false
	part.CanQuery = false
	part.CanTouch = false
	part.CastShadow = false
	part.Locked = true
end

-- Invisible host part for attachments, emitters, lights and beams.
-- Pass a lifetime to have it (and everything parented to it) auto-removed.
function Emit.anchor(cframe: CFrame, lifetime: number?, size: Vector3?): Part
	local part = Instance.new("Part")
	part.Name = "VFXAnchor"
	part.Transparency = 1
	part.Size = size or General.AnchorSize
	part.CFrame = cframe
	Emit.makeInert(part)
	part.Parent = Emit.folder()
	if lifetime then
		Emit.cleanup(part, lifetime + General.CleanupPadding)
	end
	return part
end

-- Visible effect part (shards, spikes, pages...). Not parented.
function Emit.part(size: Vector3, color: Color3, material: Enum.Material): Part
	local part = Instance.new("Part")
	part.Name = "VFXPart"
	part.Size = size
	part.Color = color
	part.Material = material
	part.TopSurface = Enum.SurfaceType.Smooth
	part.BottomSurface = Enum.SurfaceType.Smooth
	Emit.makeInert(part)
	return part
end

function Emit.attachment(parent: BasePart, offset: CFrame?): Attachment
	local attachment = Instance.new("Attachment")
	attachment.CFrame = offset or CFrame.identity
	attachment.Parent = parent
	return attachment
end

-- Builds a ParticleEmitter from a spec. Burst emitters stay disabled with
-- Rate 0 and are fired with :Emit(n); looping emitters set spec.Rate.
function Emit.emitter(parent: Instance, spec: Types.EmitterSpec): ParticleEmitter
	local emitter = Instance.new("ParticleEmitter")
	emitter.Rate = (spec.Rate or 0) * Config.Intensity.Particles
	emitter.Enabled = spec.Rate ~= nil
	emitter.Texture = spec.Texture
	emitter.Color = spec.Color
	emitter.Size = spec.Size
	emitter.Transparency = spec.Transparency
	emitter.Lifetime = spec.Lifetime
	emitter.Speed = spec.Speed
	emitter.SpreadAngle = spec.SpreadAngle or Vector2.zero
	emitter.LightEmission = spec.LightEmission or 0
	emitter.LightInfluence = spec.LightInfluence or 0
	emitter.Brightness = spec.Brightness or 1
	emitter.Rotation = spec.Rotation or NumberRange.new(0)
	emitter.RotSpeed = spec.RotSpeed or NumberRange.new(0)
	emitter.Acceleration = spec.Acceleration or Vector3.zero
	emitter.Drag = spec.Drag or 0
	emitter.ZOffset = spec.ZOffset or 0
	emitter.Orientation = spec.Orientation or Enum.ParticleOrientation.FacingCamera
	emitter.LockedToPart = spec.LockedToPart or false
	if spec.Squash then
		emitter.Squash = spec.Squash
	end
	if spec.Shape then
		emitter.Shape = spec.Shape
	end
	if spec.ShapeInOut then
		emitter.ShapeInOut = spec.ShapeInOut
	end
	if spec.ShapeStyle then
		emitter.ShapeStyle = spec.ShapeStyle
	end
	if spec.EmissionDirection then
		emitter.EmissionDirection = spec.EmissionDirection
	end
	if spec.Flipbook and Config.Flipbook.Enabled then
		emitter.FlipbookLayout = if spec.LargeFlipbook then Config.Flipbook.LargeLayout else Config.Flipbook.Layout
		emitter.FlipbookMode = Config.Flipbook.Mode
		emitter.FlipbookFramerate = Config.Flipbook.Framerate
		emitter.FlipbookStartRandom = Config.Flipbook.StartRandom
	end
	emitter.Parent = parent
	return emitter
end

-- One-shot burst at a CFrame. The host part lives exactly as long as the
-- longest particle, then Debris removes it. `size` gives the host part a
-- volume for Shape-based emitters.
function Emit.burstAt(cframe: CFrame, burst: Types.BurstSpec, size: Vector3?): ParticleEmitter
	local host = Emit.anchor(cframe, burst.Spec.Lifetime.Max, size)
	local emitter = Emit.emitter(host, burst.Spec)
	emitter:Emit(Emit.count(burst.Count))
	return emitter
end

-- Burst on an existing emitter.
function Emit.burst(emitter: ParticleEmitter, count: number)
	emitter:Emit(Emit.count(count))
end

-- Applies Config.Intensity.Particles to a particle count (always >= 1),
-- capped at Config.Intensity.MaxPerBurst to protect low-end devices.
function Emit.count(n: number): number
	local scaled = math.floor(n * Config.Intensity.Particles + 0.5)
	return math.clamp(scaled, 1, Config.Intensity.MaxPerBurst)
end

-- Per-frame callback for `duration` seconds (math.huge = until stopped).
-- fn(alpha 0..1, dt, elapsed) may return true to stop early. onDone runs
-- exactly once when the step ends for any reason. Returns a stop function.
function Emit.step(
	duration: number,
	fn: (alpha: number, dt: number, elapsed: number) -> boolean?,
	onDone: (() -> ())?
): () -> ()
	local elapsed = 0
	local connection: RBXScriptConnection? = nil
	local finished = false

	local function stop()
		if finished then
			return
		end
		finished = true
		if connection then
			connection:Disconnect()
			connection = nil
		end
		if onDone then
			onDone()
		end
	end

	connection = RunService.RenderStepped:Connect(function(dt: number)
		elapsed += dt
		local alpha = if duration == math.huge then 0 else math.clamp(elapsed / duration, 0, 1)
		local ok, result = pcall(fn, alpha, dt, elapsed)
		if not ok then
			warn("[VFX] step callback errored:", result)
			stop()
			return
		end
		if result == true or elapsed >= duration then
			stop()
		end
	end)
	return stop
end

-- Repeated :Emit(count) every `interval` seconds for `duration` seconds.
function Emit.pulse(emitter: ParticleEmitter, count: number, interval: number, duration: number): () -> ()
	if interval <= 0 then
		-- Misconfigured interval: emit once instead of looping forever.
		emitter:Emit(count)
		return function() end
	end
	local accumulator = interval -- fire immediately on the first frame
	return Emit.step(duration, function(_alpha, dt)
		if not emitter.Parent then
			return true
		end
		accumulator += dt
		while accumulator >= interval do
			accumulator -= interval
			emitter:Emit(Emit.count(count))
		end
		return false
	end)
end

-- Creates and plays a finite tween (RepeatCount 0, never reverses).
function Emit.tween(
	instance: Instance,
	duration: number,
	goals: { [string]: any },
	style: Enum.EasingStyle?,
	direction: Enum.EasingDirection?,
	delayTime: number?
): Tween
	local info = TweenInfo.new(
		duration,
		style or Enum.EasingStyle.Quad,
		direction or Enum.EasingDirection.Out,
		0,
		false,
		delayTime or 0
	)
	local tween = TweenService:Create(instance, info, goals)
	tween:Play()
	return tween
end

-- NumberSequence properties (Beam/Trail Transparency) cannot be tweened
-- directly, so this tweens a NumberValue proxy and writes a uniform
-- sequence each change. The proxy is destroyed when the tween ends.
function Emit.fadeSequence(instance: Instance, property: string, from: number, to: number, duration: number): Tween
	local proxy = Instance.new("NumberValue")
	proxy.Value = from
	local target = instance :: any
	target[property] = NumberSequence.new(from)
	local connection = proxy.Changed:Connect(function(value: number)
		if instance.Parent then
			target[property] = NumberSequence.new(value)
		end
	end)
	local tween = Emit.tween(proxy, duration, { Value = to }, Enum.EasingStyle.Linear)
	tween.Completed:Once(function()
		connection:Disconnect()
		proxy:Destroy()
	end)
	return tween
end

-- Raw downward raycast used by groundAt and RockRing (for the ground
-- material). Ignores characters and VFX. Returns nil when nothing is hit.
function Emit.groundRaycast(position: Vector3): RaycastResult?
	local ignore: { Instance } = { Emit.folder() }
	for _, player in Players:GetPlayers() do
		if player.Character then
			table.insert(ignore, player.Character)
		end
	end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = ignore
	params.IgnoreWater = false

	local origin = position + Vector3.yAxis * General.GroundRayHeight
	local direction = -Vector3.yAxis * (General.GroundRayHeight + General.GroundRayDepth)
	return Workspace:Raycast(origin, direction, params)
end

-- Ground point and surface normal under `position` (or the input position
-- and world up when nothing is hit).
function Emit.groundAt(position: Vector3): (Vector3, Vector3)
	local result = Emit.groundRaycast(position)
	if result then
		return result.Position, result.Normal
	end
	return position, Vector3.yAxis
end

-- CFrame on the ground whose UpVector is the surface normal. `forward`
-- (optional) sets the yaw; otherwise a random yaw is used.
function Emit.groundCFrame(position: Vector3, forward: Vector3?): CFrame
	local point, normal = Emit.groundAt(position)
	local look: Vector3
	if forward and forward.Magnitude >= 1e-3 then
		look = forward
	else
		local angle = rng:NextNumber(0, math.pi * 2)
		look = Vector3.new(math.cos(angle), 0, math.sin(angle))
	end
	-- Project the look direction onto the ground plane.
	local flat = look - normal * look:Dot(normal)
	if flat.Magnitude < 1e-3 then
		flat = normal:Cross(Vector3.xAxis)
	end
	local right = flat.Unit:Cross(normal)
	return CFrame.fromMatrix(point + normal * General.GroundOffset, right, normal)
end

-- Root part of a character model, if it still exists.
function Emit.root(character: Model): BasePart?
	local root = character:FindFirstChild("HumanoidRootPart")
	if root and root:IsA("BasePart") then
		return root
	end
	return nil
end

-- Position of a character's feet, correct for any rig size (a scaled-up
-- world boss included): root bottom minus the humanoid's HipHeight.
function Emit.feet(character: Model): Vector3?
	local root = Emit.root(character)
	if root == nil then
		return nil
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	local hip = if humanoid then humanoid.HipHeight else 0
	return root.Position - Vector3.yAxis * (root.Size.Y / 2 + hip)
end

-- How big a character is relative to a default R15 rig (1 = normal player,
-- ~3 = a boss scaled with Model:ScaleTo(3)). Spells use it to scale
-- character-attached effects.
function Emit.characterScale(character: Model): number
	local ok, scale = pcall(function()
		return character:GetScale()
	end)
	if ok and typeof(scale) == "number" and scale > 0 then
		return scale
	end
	return 1
end

-- Random helpers ------------------------------------------------------------
function Emit.random(min: number, max: number): number
	return rng:NextNumber(min, max)
end

function Emit.randomInt(min: number, max: number): number
	return rng:NextInteger(min, max)
end

function Emit.randomUnit(): Vector3
	return rng:NextUnitVector()
end

return Emit
]=])
make("ModuleScript", "Flash", i12, [=[
--!strict
--[[
	Flash
	=====
	Impact-moment light effects (client only):

	  * Flash.Light(pos, params)    - PointLight that tweens to darkness
	  * Flash.Streak(pos, params)   - flat horizontal lens-flare streak
	                                  (BillboardGui so it is always screen-horizontal)
	  * Flash.Screen(params, pos?)  - full-screen white flash, weaker with distance
	  * Flash.Impact(pos, preset)   - all three using a Config.Flash.Presets entry

	Every instance is destroyed by Debris once its tween finishes.
]]

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Settings = Config.Flash

local Flash = {}

function Flash.Light(position: Vector3, params: Types.LightParams): PointLight
	local duration = params.Duration or 0
	local host = Emit.anchor(CFrame.new(position), duration)
	local light = Instance.new("PointLight")
	light.Color = params.Color
	light.Brightness = params.Brightness
	light.Range = params.Range
	light.Shadows = false
	light.Parent = host
	if duration > 0 then
		Emit.tween(light, duration, { Brightness = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
	end
	return light
end

function Flash.Streak(position: Vector3, params: Types.StreakParams)
	local host = Emit.anchor(CFrame.new(position), params.Duration)

	local gui = Instance.new("BillboardGui")
	gui.Name = "FlareStreak"
	gui.Adornee = host
	gui.AlwaysOnTop = Settings.StreakAlwaysOnTop
	gui.LightInfluence = 0
	gui.Brightness = params.Brightness
	gui.Size = UDim2.fromScale(params.Width * Settings.StreakStartWidthScale, params.Height)
	gui.Parent = host

	-- Soft outer glow.
	local glow = Instance.new("Frame")
	glow.AnchorPoint = Vector2.new(0.5, 0.5)
	glow.Position = UDim2.fromScale(0.5, 0.5)
	glow.Size = UDim2.fromScale(1, 1)
	glow.BackgroundColor3 = params.Color
	glow.BorderSizePixel = 0
	glow.Parent = gui
	local glowCorner = Instance.new("UICorner")
	glowCorner.CornerRadius = UDim.new(0.5, 0)
	glowCorner.Parent = glow
	local glowGradient = Instance.new("UIGradient")
	glowGradient.Transparency = Settings.StreakGradient
	glowGradient.Parent = glow

	-- Thin, hot core line.
	local core = glow:Clone()
	core.Size = UDim2.fromScale(1, Settings.StreakCoreHeightScale)
	core.Parent = gui

	-- Optional flare texture once a real asset is uploaded.
	if Config.Textures.Flare ~= Config.PlaceholderTexture then
		local image = Instance.new("ImageLabel")
		image.BackgroundTransparency = 1
		image.Size = UDim2.fromScale(1, 1)
		image.Image = Config.Textures.Flare
		image.ImageColor3 = params.Color
		image.Parent = gui
		Emit.tween(image, params.Duration, { ImageTransparency = 1 })
	end

	Emit.tween(gui, params.Duration, { Size = UDim2.fromScale(params.Width, 0) }, Enum.EasingStyle.Quart)
	Emit.tween(glow, params.Duration, { BackgroundTransparency = 1 })
	Emit.tween(core, params.Duration, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
end

local function screenGui(): ScreenGui?
	local player = Players.LocalPlayer
	if player == nil then
		return nil
	end
	local playerGui = player:FindFirstChildOfClass("PlayerGui")
	if playerGui == nil then
		return nil
	end
	local existing = playerGui:FindFirstChild(Settings.ScreenGuiName)
	if existing and existing:IsA("ScreenGui") then
		return existing
	end
	local gui = Instance.new("ScreenGui")
	gui.Name = Settings.ScreenGuiName
	gui.IgnoreGuiInset = true
	gui.ResetOnSpawn = false
	gui.DisplayOrder = Settings.ScreenDisplayOrder
	gui.Parent = playerGui
	return gui
end

function Flash.Screen(params: Types.ScreenFlashParams, source: Vector3?)
	local gui = screenGui()
	local camera = Workspace.CurrentCamera
	if gui == nil or camera == nil then
		return
	end
	local strength = 1
	if source then
		local distance = (camera.CFrame.Position - source).Magnitude
		strength = math.clamp(1 - distance / Settings.ScreenMaxDistance, 0, 1)
	end
	if strength <= 0 then
		return
	end
	local frame = Instance.new("Frame")
	frame.Size = UDim2.fromScale(1, 1)
	frame.BorderSizePixel = 0
	frame.BackgroundColor3 = params.Color
	-- Lerp from fully transparent toward the preset opacity by strength.
	frame.BackgroundTransparency = 1 - (1 - params.Transparency) * strength
	frame.Parent = gui
	Emit.tween(frame, params.Duration, { BackgroundTransparency = 1 })
	Emit.cleanup(frame, params.Duration)
end

-- Light + streak + screen flash from a named Config.Flash.Presets entry.
function Flash.Impact(position: Vector3, presetName: string)
	local preset = (Settings.Presets :: any)[presetName] :: Types.FlashPreset?
	if preset == nil then
		warn("[VFX] Unknown flash preset:", presetName)
		return
	end
	Flash.Light(position, preset.Light)
	Flash.Streak(position, preset.Streak)
	Flash.Screen(preset.Screen, position)
end

return Flash
]=])
make("ModuleScript", "FocusLines", i12, [=[
--!strict
--[[
	FocusLines
	==========
	Anime "focus lines" / speed lines (client only): thin white streaks
	radiating from the impact point's position on screen, re-randomised
	every RerollInterval for a flickering manga look, fading out over
	Duration.

	Built from Frames inside a CanvasGroup so the whole set fades with one
	GroupTransparency tween. Everything is destroyed when it ends.

	  FocusLines.Play(worldPosition, Config...FocusLines)
]]

local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Settings = Config.FocusLines

local FocusLines = {}

local function screenGui(): ScreenGui?
	local player = Players.LocalPlayer
	local playerGui = player and player:FindFirstChildOfClass("PlayerGui")
	if playerGui == nil then
		return nil
	end
	local existing = playerGui:FindFirstChild(Settings.GuiName)
	if existing and existing:IsA("ScreenGui") then
		return existing
	end
	local gui = Instance.new("ScreenGui")
	gui.Name = Settings.GuiName
	gui.IgnoreGuiInset = true
	gui.ResetOnSpawn = false
	gui.DisplayOrder = Settings.DisplayOrder
	gui.Parent = playerGui
	return gui
end

function FocusLines.Play(worldPosition: Vector3, params: Types.FocusLineParams)
	local gui = screenGui()
	local camera = Workspace.CurrentCamera
	if gui == nil or camera == nil then
		return
	end
	local viewport = camera.ViewportSize
	local screenPoint, onScreen = camera:WorldToViewportPoint(worldPosition)
	if (camera.CFrame.Position - worldPosition).Magnitude > Settings.MaxDistance then
		return
	end
	local center = if onScreen then Vector2.new(screenPoint.X, screenPoint.Y) else viewport / 2
	local short = math.min(viewport.X, viewport.Y)

	local group = Instance.new("CanvasGroup")
	group.Size = UDim2.fromScale(1, 1)
	group.BackgroundTransparency = 1
	group.GroupTransparency = params.Transparency
	group.Parent = gui

	local taper = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 1),
		NumberSequenceKeypoint.new(Settings.TaperPeak, 0),
		NumberSequenceKeypoint.new(1, 1),
	})

	local lines: { Frame } = {}
	for _ = 1, params.Count do
		local line = Instance.new("Frame")
		line.AnchorPoint = Vector2.new(0.5, 0.5)
		line.BorderSizePixel = 0
		line.BackgroundColor3 = params.Color
		line.Parent = group
		local gradient = Instance.new("UIGradient")
		gradient.Transparency = taper
		gradient.Parent = line
		table.insert(lines, line)
	end

	local function reroll()
		for _, line in lines do
			local angle = Emit.random(0, math.pi * 2)
			local length = Emit.random(params.LengthMin, params.LengthMax) * short
			local inner = params.InnerRadius * short
			local mid = center + Vector2.new(math.cos(angle), math.sin(angle)) * (inner + length / 2)
			line.Position = UDim2.fromOffset(mid.X, mid.Y)
			line.Size = UDim2.fromOffset(length, Emit.random(params.Thickness * Settings.ThinScale, params.Thickness))
			line.Rotation = math.deg(angle)
		end
	end
	reroll()

	local accumulator = 0
	Emit.step(params.Duration, function(_alpha, dt)
		if not group.Parent then
			return true
		end
		accumulator += dt
		if accumulator >= params.RerollInterval then
			accumulator = 0
			reroll()
		end
		return false
	end, function()
		group:Destroy()
	end)
	Emit.tween(group, params.Duration, { GroupTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
	Emit.cleanup(group, params.Duration + Config.General.CleanupPadding)
end

return FocusLines
]=])
make("ModuleScript", "GroundDecal", i12, [=[
--!strict
--[[
	GroundDecal
	===========
	Cracked-ground mark that spreads out, holds, then fades (client only).

	Two layers:
	  1. A Decal (Config.Textures.Crack) on a thin flat part aligned to the
	     ground normal. Invisible until you upload a crack texture.
	  2. Procedural cracks: thin jagged parts radiating from the centre
	     ("Radial"), straight star arms ("Star") or a long slash with side
	     branches ("Slash"). These work with no textures at all.

	GroundDecal.Spawn(position, params, forward?) returns a Handle. When
	params.Hold > 0 it fades automatically; with Hold = 0 it stays until
	handle.Stop() is called (used by looping spells).
]]

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Settings = Config.GroundDecal

local GroundDecal = {}

-- Adds one thin crack segment between two points in the root's space.
local function addSegment(root: BasePart, a: Vector3, b: Vector3, cracks: Types.CrackParams, delayTime: number)
	local length = (b - a).Magnitude
	if length < 1e-3 then
		return
	end
	local segment =
		Emit.part(Vector3.new(cracks.Thickness, Settings.SegmentHeight, length), cracks.Color, cracks.Material)
	local mid = (a + b) / 2
	segment.CFrame = root.CFrame * CFrame.lookAt(mid, b, Vector3.yAxis)
	segment.Transparency = 1
	segment.Parent = root
	Emit.tween(segment, Settings.SegmentFadeIn, { Transparency = 0 }, Enum.EasingStyle.Linear, nil, delayTime)
end

-- Jagged polyline from `origin` along `direction` (local space, y = 0).
local function addCrack(
	root: BasePart,
	origin: Vector3,
	direction: Vector3,
	length: number,
	cracks: Types.CrackParams,
	startDistance: number
)
	local segments = math.max(cracks.Segments, 1)
	local step = length / segments
	local side = Vector3.new(-direction.Z, 0, direction.X)
	local previous = origin
	for i = 1, segments do
		local along = origin + direction * (step * i)
		-- Jitter fades toward the tip so cracks taper naturally.
		local jitter = if i == segments then 0 else Emit.random(-cracks.Jitter, cracks.Jitter) * step
		local point = along + side * jitter
		local distance = startDistance + step * i
		addSegment(root, previous, point, cracks, distance * Settings.SegmentDelayPerStud)
		previous = point
	end
end

local function buildCracks(root: BasePart, params: Types.GroundDecalParams, cracks: Types.CrackParams)
	local radius = params.Radius
	if cracks.Pattern == "Slash" then
		local halfLength = (params.Length or radius * 2) / 2
		-- Main slash runs along local -Z (the decal's forward).
		addCrack(root, Vector3.new(0, 0, halfLength), Vector3.new(0, 0, -1), halfLength * 2, cracks, 0)
		for _ = 1, cracks.Count do
			local z = Emit.random(-halfLength, halfLength)
			local sideSign = if Emit.randomInt(0, 1) == 1 then 1 else -1
			local angle = Emit.random(Settings.SlashBranchAngleMin, Settings.SlashBranchAngleMax) * sideSign
			local direction = Vector3.new(math.sin(angle), 0, -math.cos(angle))
			addCrack(root, Vector3.new(0, 0, z), direction, radius, cracks, halfLength - z)
		end
		return
	end

	local count = math.max(cracks.Count, 1)
	for i = 1, count do
		local angle = (i / count) * math.pi * 2
		if cracks.Pattern ~= "Star" then
			angle += Emit.random(-Settings.RadialAngleJitter, Settings.RadialAngleJitter) * (math.pi * 2 / count)
		end
		local direction = Vector3.new(math.cos(angle), 0, math.sin(angle))
		local length = if cracks.Pattern == "Star" then radius else radius * Emit.random(Settings.RadialLengthMin, 1)
		addCrack(root, Vector3.zero, direction, length, cracks, 0)
		-- Star pattern: a short side spike on each arm for the frost look.
		if cracks.Pattern == "Star" then
			local branchAngle = angle + math.pi / count
			local branch = Vector3.new(math.cos(branchAngle), 0, math.sin(branchAngle))
			addCrack(root, Vector3.zero, branch, radius * Settings.StarBranchScale, cracks, 0)
		end
	end
end

function GroundDecal.Spawn(position: Vector3, params: Types.GroundDecalParams, forward: Vector3?): Types.Handle
	local cframe = Emit.groundCFrame(position, forward)
	local width = params.Radius * 2
	local length = params.Length or width
	local fullSize = Vector3.new(width, Settings.Thickness, length)

	local root = Emit.part(
		fullSize * Vector3.new(params.StartScale, 1, params.StartScale),
		params.Color,
		Enum.Material.SmoothPlastic
	)
	root.Name = "GroundDecal"
	root.Transparency = 1
	root.CFrame = cframe
	root.Parent = Emit.folder()

	local decal: Decal? = nil
	if params.Texture ~= Config.PlaceholderTexture then
		local d = Instance.new("Decal")
		d.Texture = params.Texture
		d.Color3 = params.Color
		d.Face = Enum.NormalId.Top
		d.Transparency = Settings.DecalTransparency
		d.Parent = root
		decal = d
	end
	Emit.tween(root, params.SpreadTime, { Size = fullSize }, Enum.EasingStyle.Quint)

	-- Cracks are built at full size; their staggered fade-in sells the spread.
	local cracks = params.Cracks
	if cracks then
		buildCracks(root, params, cracks)
	end

	local faded = false
	local function fade()
		if faded then
			return
		end
		faded = true
		if not root.Parent then
			return
		end
		if decal then
			Emit.tween(decal, params.FadeTime, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		end
		for _, child in root:GetChildren() do
			if child:IsA("BasePart") then
				Emit.tween(child, params.FadeTime, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
		end
		Emit.cleanup(root, params.FadeTime + Config.General.CleanupPadding)
	end

	if params.Hold > 0 then
		-- Delayed fade with no yielding: Debris guarantees removal even if the
		-- delayed callback were somehow skipped.
		task.delay(params.SpreadTime + params.Hold, fade)
		Emit.cleanup(root, params.SpreadTime + params.Hold + params.FadeTime + Config.General.CleanupPadding)
	end

	return { Stop = fade }
end

return GroundDecal
]=])
make("ModuleScript", "ImpactFrame", i12, [=[
--!strict
--[[
	ImpactFrame
	===========
	Anime-style impact frames (client only). For a few frames the whole
	screen snaps to stark, high-contrast black and white (optionally with a
	full-screen colour flash), alternating between steps, then returns to
	normal.

	Implemented with a temporary ColorCorrectionEffect in Lighting plus a
	full-screen Frame. Both are destroyed when the sequence ends. Viewers
	further than params.MaxDistance from the source see nothing.

	  ImpactFrame.Play(Config.ImpactFrame.Presets.Heavy, impactPosition)
	  ImpactFrame.Preset("Heavy", impactPosition)
]]

local Lighting = game:GetService("Lighting")
local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Settings = Config.ImpactFrame

local ImpactFrame = {}

local function overlayGui(): ScreenGui?
	local player = Players.LocalPlayer
	local playerGui = player and player:FindFirstChildOfClass("PlayerGui")
	if playerGui == nil then
		return nil
	end
	local existing = playerGui:FindFirstChild(Settings.GuiName)
	if existing and existing:IsA("ScreenGui") then
		return existing
	end
	local gui = Instance.new("ScreenGui")
	gui.Name = Settings.GuiName
	gui.IgnoreGuiInset = true
	gui.ResetOnSpawn = false
	gui.DisplayOrder = Settings.DisplayOrder
	gui.Parent = playerGui
	return gui
end

function ImpactFrame.Play(params: Types.ImpactFrameParams, source: Vector3?)
	if not Settings.Enabled or #params.Frames == 0 then
		return
	end
	local camera = Workspace.CurrentCamera
	if source and camera and (camera.CFrame.Position - source).Magnitude > params.MaxDistance then
		return
	end

	local effect = Instance.new("ColorCorrectionEffect")
	effect.Name = Settings.EffectName
	effect.Parent = Lighting

	local overlay: Frame? = nil
	local gui = overlayGui()
	if gui then
		local frame = Instance.new("Frame")
		frame.Size = UDim2.fromScale(1, 1)
		frame.BorderSizePixel = 0
		frame.BackgroundTransparency = 1
		frame.Parent = gui
		overlay = frame
	end

	local total = 0
	for _, step in params.Frames do
		total += step.Duration
	end

	local current = 0
	local function apply(index: number)
		local step = params.Frames[index]
		effect.Saturation = step.Saturation
		effect.Contrast = step.Contrast
		effect.Brightness = step.Brightness
		effect.TintColor = step.TintColor
		if overlay then
			if step.Overlay then
				overlay.BackgroundColor3 = step.Overlay
				overlay.BackgroundTransparency = step.OverlayTransparency or 0
			else
				overlay.BackgroundTransparency = 1
			end
		end
	end

	Emit.step(total, function(_alpha, _dt, elapsed)
		-- Find which step `elapsed` falls into.
		local acc = 0
		local index = #params.Frames
		for i, step in params.Frames do
			acc += step.Duration
			if elapsed < acc then
				index = i
				break
			end
		end
		if index ~= current then
			current = index
			apply(index)
		end
		return false
	end, function()
		effect:Destroy()
		if overlay then
			overlay:Destroy()
		end
	end)
	-- Safety net in case the render step never runs (e.g. window minimised).
	Emit.cleanup(effect, total + Config.General.CleanupPadding)
	if overlay then
		Emit.cleanup(overlay, total + Config.General.CleanupPadding)
	end
end

function ImpactFrame.Preset(name: string, source: Vector3?)
	local preset = (Settings.Presets :: any)[name] :: Types.ImpactFrameParams?
	if preset then
		ImpactFrame.Play(preset, source)
	else
		warn("[VFX] Unknown impact frame preset:", name)
	end
end

return ImpactFrame
]=])
make("ModuleScript", "Lightning", i12, [=[
--!strict
--[[
	Lightning
	=========
	Jagged electric bolts built from chains of straight Beams (client only).
	Each bolt is a polyline of attachments with random perpendicular offsets
	(strongest in the middle, zero at the ends). The offsets are re-rolled
	every `FlickerInterval` seconds so the bolt crackles, and optional
	branches fork off the main chain. When Duration ends the bolt fades over
	FadeTime and its host part is destroyed.

	  * Lightning.Strike(from, to, params)          - fixed endpoints
	  * Lightning.Crawl(from, to, crawlTime, params) - tip creeps from -> to
	  * Lightning.Crackle(center, radius, count, params) - arcs jumping around a core
	  * Lightning.GroundArcs(center, arcParams)     - arcs crawling outward on the floor
	  * Lightning.Bolt(getEndpoints, params)        - generic form used by the above
]]

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Settings = Config.Lightning

export type GroundArcParams = {
	Count: number,
	Length: number,
	CrawlTime: number,
	Bolt: Types.BoltParams,
	Lift: number,
}

type Chain = {
	Attachments: { Attachment },
	Beams: { Beam },
	Widths: { number },
}

type Branch = {
	Chain: Chain,
	RootIndex: number,
	Amplitude: number,
}

local Lightning = {}

local function basis(direction: Vector3): (Vector3, Vector3)
	local dir = if direction.Magnitude > 1e-4 then direction.Unit else Vector3.yAxis
	local reference = if math.abs(dir:Dot(Vector3.yAxis)) > Settings.MinPerpendicularCheck
		then Vector3.xAxis
		else Vector3.yAxis
	local u = dir:Cross(reference).Unit
	local v = dir:Cross(u).Unit
	return u, v
end

local function buildChain(host: BasePart, segments: number, params: Types.BoltParams, widthScale: number): Chain
	local attachments: { Attachment } = {}
	for i = 1, segments + 1 do
		attachments[i] = Emit.attachment(host)
	end
	local beams: { Beam } = {}
	local widths: { number } = {}
	local baseTransparency = params.Transparency or 0
	for i = 1, segments do
		local beam = Instance.new("Beam")
		beam.Attachment0 = attachments[i]
		beam.Attachment1 = attachments[i + 1]
		beam.Color = ColorSequence.new(params.Color)
		beam.LightEmission = params.LightEmission
		beam.LightInfluence = 0
		beam.Brightness = params.Brightness
		beam.FaceCamera = true
		beam.Segments = 1
		beam.Transparency = NumberSequence.new(baseTransparency)
		-- Taper from full width at the start to EndWidthScale at the tip.
		local t0 = (i - 1) / segments
		local t1 = i / segments
		local scale = params.Width * widthScale
		beam.Width0 = scale * (1 + (params.EndWidthScale - 1) * t0)
		beam.Width1 = scale * (1 + (params.EndWidthScale - 1) * t1)
		widths[(i - 1) * 2 + 1] = beam.Width0
		widths[(i - 1) * 2 + 2] = beam.Width1
		beam.Parent = host
		beams[i] = beam
	end
	return { Attachments = attachments, Beams = beams, Widths = widths }
end

local function layoutChain(chain: Chain, from: Vector3, to: Vector3, amplitude: number)
	local u, v = basis(to - from)
	local count = #chain.Attachments - 1
	for i, attachment in chain.Attachments do
		local t = (i - 1) / count
		local envelope = math.sin(math.pi * t)
		local offset = (u * Emit.random(-1, 1) + v * Emit.random(-1, 1)) * amplitude * envelope
		attachment.WorldPosition = from:Lerp(to, t) + offset
	end
end

local function setFade(chain: Chain, fade: number, baseTransparency: number)
	local transparency = NumberSequence.new(baseTransparency + (1 - baseTransparency) * fade)
	local keep = 1 - fade
	for i, beam in chain.Beams do
		beam.Transparency = transparency
		beam.Width0 = chain.Widths[(i - 1) * 2 + 1] * keep
		beam.Width1 = chain.Widths[(i - 1) * 2 + 2] * keep
	end
end

-- Generic bolt. getEndpoints(elapsed) is called on every rebuild, so
-- endpoints can move (crawl) or jump (crackle).
function Lightning.Bolt(getEndpoints: (elapsed: number) -> (Vector3, Vector3), params: Types.BoltParams): Types.Handle
	local from, to = getEndpoints(0)
	local total = params.Duration + params.FadeTime
	local host = Emit.anchor(CFrame.new(from), total)
	local baseTransparency = params.Transparency or 0

	local main = buildChain(host, math.max(params.Segments, 1), params, 1)
	local branches: { Branch } = {}
	local branchParams = params.Branches
	if branchParams and params.Segments > 2 then
		for _ = 1, branchParams.Count do
			table.insert(branches, {
				Chain = buildChain(host, math.max(branchParams.Segments, 1), params, branchParams.WidthScale),
				RootIndex = Emit.randomInt(2, params.Segments),
				Amplitude = branchParams.Amplitude,
			})
		end
	end

	local function rebuild(elapsed: number)
		from, to = getEndpoints(elapsed)
		layoutChain(main, from, to, params.Amplitude)
		if branchParams then
			local length = (to - from).Magnitude * branchParams.LengthScale
			local direction = if (to - from).Magnitude > 1e-4 then (to - from).Unit else Vector3.yAxis
			for _, branch in branches do
				local start = main.Attachments[branch.RootIndex].WorldPosition
				local deviation = (direction + Emit.randomUnit() * Settings.BranchDeviation).Unit
				layoutChain(branch.Chain, start, start + deviation * length, branch.Amplitude)
			end
		end
	end

	rebuild(0)
	local accumulator = 0
	local stopStep = Emit.step(total, function(_alpha, dt, elapsed)
		if not host.Parent then
			return true
		end
		accumulator += dt
		if accumulator >= params.FlickerInterval then
			accumulator = 0
			rebuild(elapsed)
		end
		if elapsed > params.Duration and params.FadeTime > 0 then
			local fade = math.clamp((elapsed - params.Duration) / params.FadeTime, 0, 1)
			setFade(main, fade, baseTransparency)
			for _, branch in branches do
				setFade(branch.Chain, fade, baseTransparency)
			end
		end
		return false
	end, function()
		host:Destroy()
	end)

	return { Stop = stopStep }
end

function Lightning.Strike(from: Vector3, to: Vector3, params: Types.BoltParams): Types.Handle
	return Lightning.Bolt(function()
		return from, to
	end, params)
end

function Lightning.Crawl(from: Vector3, to: Vector3, crawlTime: number, params: Types.BoltParams): Types.Handle
	return Lightning.Bolt(function(elapsed: number)
		local t = if crawlTime > 0 then math.clamp(elapsed / crawlTime, 0, 1) else 1
		return from, from:Lerp(to, t)
	end, params)
end

-- `count` short arcs that jump to new random spots around `center`.
function Lightning.Crackle(center: Vector3, radius: number, count: number, params: Types.BoltParams)
	for _ = 1, count do
		Lightning.Bolt(function()
			local a = center + Emit.randomUnit() * radius * Emit.random(Settings.CrackleInnerScale, 1)
			local b = center + Emit.randomUnit() * radius * Emit.random(Settings.CrackleInnerScale, 1)
			return a, b
		end, params)
	end
end

-- Arcs that crawl outward along the ground from `center`.
function Lightning.GroundArcs(center: Vector3, arc: GroundArcParams)
	local ground = Emit.groundAt(center)
	local lift = Vector3.yAxis * arc.Lift
	for i = 1, arc.Count do
		local angle = (i / arc.Count) * math.pi * 2 + Emit.random(-Settings.ArcAngleJitter, Settings.ArcAngleJitter)
		local direction = Vector3.new(math.cos(angle), 0, math.sin(angle))
		local reach = arc.Length * Emit.random(Settings.ArcLengthMin, 1)
		local endPoint = Emit.groundAt(ground + direction * reach)
		Lightning.Crawl(ground + lift, endPoint + lift, arc.CrawlTime, arc.Bolt)
	end
end

return Lightning
]=])
make("ModuleScript", "OrbitTrail", i12, [=[
--!strict
--[[
	OrbitTrail
	==========
	White ring trails that orbit a character (or any moving centre). Each
	orbit is an invisible anchored part repositioned every frame on a tilted
	circle around the centre; a Trail between two attachments on that part
	draws the glowing ring. Optional RiseSpeed turns the circle into a
	rising helix (used for spiralling smoke).

	  local handle = OrbitTrail.OnCharacter(character, orbit, style, duration?)
	  handle.Stop()  -- optional; also stops automatically after `duration`
	                 -- or when the centre disappears

	After stopping, the part lives for one trail Lifetime so the tail fades
	out naturally, then Debris removes it.
]]

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local OrbitTrail = {}

function OrbitTrail.Start(
	getCenter: () -> CFrame?,
	orbit: Types.OrbitParams,
	style: Types.TrailStyle,
	duration: number?
): Types.Handle
	local part = Emit.part(Config.General.AnchorSize, style.Color, Enum.Material.SmoothPlastic)
	part.Name = Config.OrbitTrail.PartName
	part.Transparency = 1

	local halfWidth = style.Width / 2
	local a0 = Emit.attachment(part, CFrame.new(0, halfWidth, 0))
	local a1 = Emit.attachment(part, CFrame.new(0, -halfWidth, 0))

	local trail = Instance.new("Trail")
	trail.Attachment0 = a0
	trail.Attachment1 = a1
	trail.Lifetime = style.Lifetime
	trail.Color = ColorSequence.new(style.Color)
	trail.Transparency = style.Transparency
	trail.LightEmission = style.LightEmission
	trail.LightInfluence = 0
	trail.Brightness = style.Brightness
	trail.FaceCamera = true
	trail.MinLength = 0
	trail.Enabled = false
	trail.Parent = part

	local tilt = CFrame.Angles(math.rad(orbit.Tilt.X), math.rad(orbit.Tilt.Y), math.rad(orbit.Tilt.Z))
	local angle = orbit.Phase
	local height = orbit.Height
	local riseSpeed = orbit.RiseSpeed or 0

	local function place(): boolean
		local center = getCenter()
		if center == nil then
			return false
		end
		part.CFrame = center
			* CFrame.new(0, height, 0)
			* tilt
			* CFrame.Angles(0, angle, 0)
			* CFrame.new(orbit.Radius, 0, 0)
		return true
	end

	if not place() then
		part:Destroy()
		return { Stop = function() end }
	end
	part.Parent = Emit.folder()
	trail.Enabled = true

	local stopStep = Emit.step(duration or math.huge, function(_alpha, dt)
		angle += orbit.Speed * dt
		height += riseSpeed * dt
		return not place()
	end, function()
		trail.Enabled = false
		Emit.cleanup(part, style.Lifetime)
	end)

	return { Stop = stopStep }
end

-- Orbit around a character's HumanoidRootPart (position only, so the ring
-- does not swing when the character turns).
function OrbitTrail.OnCharacter(
	character: Model,
	orbit: Types.OrbitParams,
	style: Types.TrailStyle,
	duration: number?
): Types.Handle
	return OrbitTrail.Start(function(): CFrame?
		local root = Emit.root(character)
		if root == nil or not character.Parent then
			return nil
		end
		return CFrame.new(root.Position)
	end, orbit, style, duration)
end

return OrbitTrail
]=])
make("ModuleScript", "RockRing", i12, [=[
--!strict
--[[
	RockRing
	========
	Chunks of ground erupting upward (client only), the classic heavy-hit
	Roblox VFX. Rocks punch up out of the floor with a Back ease, lean
	outward, hold, then sink back down and are destroyed.

	With UseGroundMaterial the rocks copy the material and colour of
	whatever is underneath (a part's Material/Color, or the Terrain
	material colour), so they match any map.

	  RockRing.Ring(center, params)          - circle of rocks
	  RockRing.Line(from, to, params)        - two rows along a path (slashes)
]]

local Workspace = game:GetService("Workspace")

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Settings = Config.RockRing

local RockRing = {}

type GroundLook = { Material: Enum.Material, Color: Color3 }

local function groundLook(position: Vector3, params: Types.RockParams): GroundLook
	if not params.UseGroundMaterial then
		return { Material = params.Material, Color = params.Color }
	end
	local result = Emit.groundRaycast(position)
	if result == nil then
		return { Material = params.Material, Color = params.Color }
	end
	local hit = result.Instance
	if hit:IsA("Terrain") then
		local ok, color = pcall(function()
			return Workspace.Terrain:GetMaterialColor(result.Material)
		end)
		return { Material = result.Material, Color = if ok then color else params.Color }
	end
	if hit:IsA("BasePart") then
		return { Material = hit.Material, Color = hit.Color }
	end
	return { Material = params.Material, Color = params.Color }
end

-- Raises one rock whose final resting CFrame is `final`.
local function raise(final: CFrame, size: Vector3, look: GroundLook, params: Types.RockParams, delayTime: number)
	local rock = Emit.part(size, look.Color, look.Material)
	rock.Name = "Rock"
	local buried = final * CFrame.new(0, -size.Y * Settings.BuryDepth, 0)
	rock.CFrame = buried
	rock.Parent = Emit.folder()
	Emit.cleanup(rock, delayTime + params.RiseTime + params.Hold + params.SinkTime + Config.General.CleanupPadding)

	local rise = Emit.tween(
		rock,
		params.RiseTime,
		{ CFrame = final },
		Enum.EasingStyle.Back,
		Enum.EasingDirection.Out,
		delayTime
	)
	rise.Completed:Once(function(state: Enum.PlaybackState)
		if state ~= Enum.PlaybackState.Completed or not rock.Parent then
			return
		end
		Emit.tween(
			rock,
			params.SinkTime,
			{ CFrame = buried, Transparency = Settings.SinkTransparency },
			Enum.EasingStyle.Quad,
			Enum.EasingDirection.In,
			params.Hold
		)
	end)
end

local function rockSize(params: Types.RockParams): Vector3
	local base = Emit.random(params.SizeMin, params.SizeMax)
	return Vector3.new(
		base * Emit.random(Settings.AspectMin, Settings.AspectMax),
		base * Emit.random(Settings.AspectMin, Settings.AspectMax),
		base * Emit.random(Settings.AspectMin, Settings.AspectMax)
	)
end

local function placeRock(
	point: Vector3,
	outward: Vector3,
	params: Types.RockParams,
	delayTime: number,
	look: GroundLook
)
	local ground = Emit.groundAt(point)
	local size = rockSize(params)
	local tilt = math.rad(Emit.random(params.TiltMin, params.TiltMax))
	-- Face outward, lean back away from the centre, add a random twist.
	local facing = CFrame.lookAt(ground, ground + outward)
	local final = facing
		* CFrame.Angles(-tilt, 0, 0)
		* CFrame.Angles(0, Emit.random(-math.pi, math.pi), 0)
		* CFrame.new(0, size.Y * Settings.ExposedHeight, 0)
	raise(final, size, look, params, delayTime)
end

function RockRing.Ring(center: Vector3, params: Types.RockParams)
	local look = groundLook(center, params)
	local count = math.max(params.Count, 1)
	for i = 1, count do
		local angle = (i / count) * math.pi * 2 + Emit.random(-Settings.AngleJitter, Settings.AngleJitter)
		local outward = Vector3.new(math.cos(angle), 0, math.sin(angle))
		local radius = params.Radius + Emit.random(-params.RadiusJitter, params.RadiusJitter)
		placeRock(center + outward * radius, outward, params, (i - 1) * params.Stagger, look)
	end
end

function RockRing.Line(from: Vector3, to: Vector3, params: Types.RockParams)
	local flat = (to - from) * Vector3.new(1, 0, 1)
	local length = flat.Magnitude
	if length < 1e-3 then
		return
	end
	local direction = flat.Unit
	local side = direction:Cross(Vector3.yAxis)
	local spacing = params.Spacing or params.SizeMax
	local look = groundLook(from, params)
	local steps = math.max(math.floor(length / spacing), 1)
	for i = 0, steps do
		local along = from + direction * (i * spacing)
		for _, sign in { 1, -1 } do
			local offset = params.Radius + Emit.random(-params.RadiusJitter, params.RadiusJitter)
			placeRock(along + side * sign * offset, side * sign, params, i * params.Stagger, look)
		end
	end
end

return RockRing
]=])
make("ModuleScript", "RuneCircle", i12, [=[
--!strict
--[[
	RuneCircle
	==========
	A magic seal drawn with glowing Beams (client only): outer circle, inner
	circle, a star polygon {StarPoints/StarStep} and radial tick marks. The
	lines "draw themselves" in order over DrawTime, the whole seal rotates
	slowly, holds, then fades out and is destroyed.

	  local handle = RuneCircle.Spawn(cframe, params)
	  -- seal lies in the XZ plane of `cframe`
	  handle.Stop() -- fade out early (optional)

	If Config.Textures.Rune is uploaded, a textured decal disc is added
	under the beam lines as well.
]]

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Settings = Config.RuneCircle

type Line = {
	From: Vector3,
	To: Vector3,
	Start: number, -- 0..1 fraction of DrawTime when this line starts drawing
	A1: Attachment,
	Beam: Beam,
}

local RuneCircle = {}

local function onCircle(radius: number, angle: number): Vector3
	return Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius)
end

function RuneCircle.Spawn(cframe: CFrame, params: Types.RuneCircleParams): Types.Handle
	local base = cframe * CFrame.new(0, params.Lift, 0)
	local host = Emit.anchor(base)
	local lines: { Line } = {}

	local function addLine(from: Vector3, to: Vector3, start: number)
		local a0 = Emit.attachment(host, CFrame.new(from))
		local a1 = Emit.attachment(host, CFrame.new(from))
		local beam = Instance.new("Beam")
		beam.Attachment0 = a0
		beam.Attachment1 = a1
		beam.Color = ColorSequence.new(params.Color)
		beam.LightEmission = params.LightEmission
		beam.LightInfluence = 0
		beam.Brightness = params.Brightness
		beam.Width0 = params.Width
		beam.Width1 = params.Width
		beam.FaceCamera = true
		beam.Segments = 1
		beam.Enabled = false
		beam.Parent = host
		table.insert(lines, { From = from, To = to, Start = start, A1 = a1, Beam = beam })
	end

	local outer = params.Radius
	local inner = params.Radius * params.InnerRadiusScale
	local segments = Settings.ArcSegments
	local order = Settings.DrawOrder

	-- Circles, drawn around their circumference.
	for i = 1, segments do
		local a = (i - 1) / segments * math.pi * 2
		local b = i / segments * math.pi * 2
		local f = (i - 1) / segments
		addLine(onCircle(outer, a), onCircle(outer, b), order.Outer[1] + (order.Outer[2] - order.Outer[1]) * f)
		addLine(onCircle(inner, a), onCircle(inner, b), order.Inner[1] + (order.Inner[2] - order.Inner[1]) * f)
	end

	-- Star polygon inside the inner circle.
	local points = math.max(params.StarPoints, 3)
	for k = 0, points - 1 do
		local a = k / points * math.pi * 2
		local b = ((k + params.StarStep) % points) / points * math.pi * 2
		local f = k / points
		addLine(onCircle(inner, a), onCircle(inner, b), order.Star[1] + (order.Star[2] - order.Star[1]) * f)
	end

	-- Tick marks between the circles.
	for t = 0, params.Ticks - 1 do
		local a = t / params.Ticks * math.pi * 2
		local f = t / math.max(params.Ticks, 1)
		addLine(
			onCircle(outer, a),
			onCircle(outer - params.TickLength, a),
			order.Ticks[1] + (order.Ticks[2] - order.Ticks[1]) * f
		)
	end

	-- Optional textured disc once a rune texture is uploaded.
	local decal: Decal? = nil
	if Config.Textures.Rune ~= Config.PlaceholderTexture then
		local disc = Emit.part(
			Vector3.new(outer * 2, Config.Shockwave.FlatThickness, outer * 2),
			params.Color,
			Enum.Material.SmoothPlastic
		)
		disc.Transparency = 1
		disc.CFrame = base
		disc.Parent = host
		local d = Instance.new("Decal")
		d.Texture = Config.Textures.Rune
		d.Color3 = params.Color
		d.Face = Enum.NormalId.Top
		d.Transparency = 1
		d.Parent = disc
		Emit.tween(d, params.DrawTime, { Transparency = 0 })
		decal = d
	end

	local drawDuration = params.DrawTime * Settings.LineDrawFraction
	local fadeStart: number? = nil
	local angle = 0
	local holdEnd = params.DrawTime + params.Hold
	local stopFade = false

	Emit.step(math.huge, function(_alpha, dt, elapsed)
		if not host.Parent then
			return true
		end
		angle += params.RotationSpeed * dt
		host.CFrame = base * CFrame.Angles(0, angle, 0)

		-- Draw phase: each line grows from its start point to its end point.
		for _, line in lines do
			local startTime = line.Start * (params.DrawTime - drawDuration)
			local t = math.clamp((elapsed - startTime) / drawDuration, 0, 1)
			if t > 0 then
				line.Beam.Enabled = true
				line.A1.Position = line.From:Lerp(line.To, t)
			end
		end

		if fadeStart == nil and (elapsed >= holdEnd or stopFade) then
			fadeStart = elapsed
			if decal then
				Emit.tween(decal, params.FadeTime, { Transparency = 1 })
			end
		end
		local started = fadeStart
		if started then
			local fade = math.clamp((elapsed - started) / params.FadeTime, 0, 1)
			local transparency = NumberSequence.new(fade)
			for _, line in lines do
				line.Beam.Transparency = transparency
			end
			return fade >= 1
		end
		return false
	end, function()
		host:Destroy()
	end)

	-- Safety net: never outlive the configured timeline.
	Emit.cleanup(host, holdEnd + params.FadeTime + Config.General.CleanupPadding)

	return {
		Stop = function()
			stopFade = true
		end,
	}
end

return RuneCircle
]=])
make("ModuleScript", "Shockwave", i12, [=[
--!strict
--[[
	Shockwave
	=========
	Expanding ring made from a loop of camera-facing Beams (client only).
	Every frame the ring's attachments are pushed outward, the beam width
	thins and the transparency rises, so the ring needs no textures.

	  * Shockwave.Ring(cframe, params)   - full ring (or partial arc when
	                                       params.ArcSpan is set) lying in the
	                                       XZ plane of `cframe`
	  * Shockwave.Ground(position, params) - flat ring on the ground, plus a
	                                       textured ring decal when
	                                       Config.Textures.Ring is uploaded

	The host part is removed by Debris right after the ring finishes.
]]

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Shockwave = {}

local function easeOut(alpha: number): number
	return 1 - (1 - alpha) ^ 3
end

function Shockwave.Ring(cframe: CFrame, params: Types.RingParams)
	local host = Emit.anchor(cframe, params.Duration + (params.Delay or 0))
	local span = params.ArcSpan or math.pi * 2
	local closed = params.ArcSpan == nil
	local segments = math.max(params.Segments, 3)
	local pointCount = if closed then segments else segments + 1

	local attachments: { Attachment } = {}
	local angles: { number } = {}
	for i = 1, pointCount do
		local angle = -span / 2 + span * ((i - 1) / segments)
		angles[i] = angle
		attachments[i] = Emit.attachment(host)
	end

	local beams: { Beam } = {}
	for i = 1, segments do
		local beam = Instance.new("Beam")
		beam.Attachment0 = attachments[i]
		beam.Attachment1 = attachments[if closed then (i % pointCount) + 1 else i + 1]
		beam.Color = ColorSequence.new(params.Color)
		beam.LightEmission = params.LightEmission
		beam.LightInfluence = 0
		beam.Brightness = params.Brightness
		beam.FaceCamera = true
		beam.Segments = 1
		beam.Width0 = params.Width
		beam.Width1 = params.Width
		beam.Transparency = NumberSequence.new(1)
		beam.Parent = host
		beams[i] = beam
	end

	local function layout(alpha: number)
		local eased = easeOut(alpha)
		local radius = params.StartRadius + (params.EndRadius - params.StartRadius) * eased
		for i, attachment in attachments do
			local angle = angles[i]
			attachment.Position = Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius)
		end
		local width = params.Width * (1 - eased)
		local transparency = NumberSequence.new(alpha * alpha)
		for i, beam in beams do
			-- Partial arcs taper at their ends.
			local w0, w1 = width, width
			if not closed then
				w0 = width * math.sin(math.pi * (i - 1) / segments)
				w1 = width * math.sin(math.pi * i / segments)
			end
			beam.Width0 = w0
			beam.Width1 = w1
			beam.Transparency = transparency
		end
	end

	local function start()
		if not host.Parent then
			return
		end
		layout(0)
		Emit.step(params.Duration, function(alpha)
			if not host.Parent then
				return true
			end
			layout(alpha)
			return false
		end)
	end

	if params.Delay and params.Delay > 0 then
		task.delay(params.Delay, start)
	else
		start()
	end
end

function Shockwave.Ground(position: Vector3, params: Types.RingParams)
	local cframe = Emit.groundCFrame(position)
	Shockwave.Ring(cframe, params)

	if Config.Textures.Ring == Config.PlaceholderTexture then
		return
	end
	local delayTime = params.Delay or 0
	local thickness = Config.Shockwave.FlatThickness
	local disc = Emit.part(
		Vector3.new(params.StartRadius * 2, thickness, params.StartRadius * 2),
		params.Color,
		Enum.Material.SmoothPlastic
	)
	disc.Transparency = 1
	disc.CFrame = cframe
	disc.Parent = Emit.folder()
	local decal = Instance.new("Decal")
	decal.Texture = Config.Textures.Ring
	decal.Color3 = params.Color
	decal.Face = Enum.NormalId.Top
	decal.Parent = disc
	local endSize = Vector3.new(params.EndRadius * 2, thickness, params.EndRadius * 2)
	Emit.tween(disc, params.Duration, { Size = endSize }, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out, delayTime)
	Emit.tween(decal, params.Duration, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, delayTime)
	Emit.cleanup(disc, params.Duration + delayTime + Config.General.CleanupPadding)
end

return Shockwave
]=])
make("ModuleScript", "Sphere", i12, [=[
--!strict
--[[
	Sphere
	======
	Expanding energy spheres (client only): a Ball part that swells from
	StartSize to EndSize while fading out. Neon material reads as a solid
	burst of light; ForceField material gives a shimmering shell. Removed by
	Debris after its tween.

	  Sphere.Burst(position, params)
]]

local Config = require(script.Parent.Parent.Config)
local Emit = require(script.Parent.Emit)
local Types = require(script.Parent.Types)

local Sphere = {}

local function burstNow(position: Vector3, params: Types.SphereParams)
	local ball = Emit.part(Vector3.one * params.StartSize, params.Color, params.Material)
	ball.Name = "EnergySphere"
	ball.Shape = Enum.PartType.Ball
	ball.Transparency = params.StartTransparency
	ball.CFrame = CFrame.new(position)
	ball.Parent = Emit.folder()
	Emit.tween(
		ball,
		params.Duration,
		{ Size = Vector3.one * params.EndSize },
		Enum.EasingStyle.Quart,
		Enum.EasingDirection.Out
	)
	Emit.tween(ball, params.Duration, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
	Emit.cleanup(ball, params.Duration + Config.General.CleanupPadding)
end

function Sphere.Burst(position: Vector3, params: Types.SphereParams)
	local delayTime = params.Delay or 0
	if delayTime > 0 then
		task.delay(delayTime, burstNow, position, params)
	else
		burstNow(position, params)
	end
end

-- Several spheres at once (e.g. a hot white core inside a dark shell).
function Sphere.Layers(position: Vector3, layers: { Types.SphereParams })
	for _, layer in layers do
		Sphere.Burst(position, layer)
	end
end

return Sphere
]=])
